    #[tokio::test]
    async fn a_public_channel_reads_history_across_a_refounding() {
        // CORD-03 §3: after a Refounding rolls the base root, a Public channel's
        // pre-rotation messages stay readable (the prior epoch's root is archived and
        // the read fans out across held epochs).
        let (_tmp, _guard, _owner) = init_test_db();
        let relay = MemoryRelay::new();
        let community = create_community(&relay, "History", vec!["wss://r".into()], None).await.unwrap();
        let general = community.channels[0].id;
        send_message(&relay, &community, &general, "before the refounding").await.unwrap();

        let refounded = refound_community(&relay, &community, &[]).await.unwrap();
        assert_eq!(refounded.root_epoch, Epoch(1), "the epoch advanced");
        send_message(&relay, &refounded, &general, "after the refounding").await.unwrap();

        let open = texts_in(&relay, &refounded, &general).await;
        assert!(open.contains(&"after the refounding".to_string()), "opening reads the live epoch");
        assert!(
            !open.contains(&"before the refounding".to_string()),
            "and NOT the rotated-past one — that plane is the back-paging cursor's job"
        );
        let paged = all_texts_in(&relay, &refounded, &general).await;
        assert!(paged.contains(&"before the refounding".to_string()), "the epoch-0 message stays reachable by paging");
        assert!(paged.contains(&"after the refounding".to_string()), "alongside the epoch-1 one");
    }

    #[tokio::test]
    async fn refounding_aborts_when_control_state_is_withheld() {
        // B1 coverage gate (CORD-06 §3): a relay serving none of the committed control
        // heads must ABORT the Refounding — never silently drop state (e.g. unban a
        // member at the new epoch a fresh joiner bootstraps).
        let (_tmp, _guard, owner) = init_test_db();
        let relay = MemoryRelay::new();
        let community = create_community(&relay, "Withheld", vec!["wss://good".into()], None).await.unwrap();
        publish_banlist(&relay, &community, &owner, &["cc".repeat(32)], 1).await;
        follow_control(&relay, &community).await.unwrap().updated; // seed the banlist floor

        // Re-point the held community to an EMPTY relay + save, so the Refounding (which
        // reloads fresh state) fetches none of the committed heads.
        let mut moved = crate::db::community::load_community_v2(community.id()).unwrap().unwrap();
        moved.relays = vec!["wss://empty".into()];
        crate::db::community::save_community_v2(&moved).unwrap();

        let err = refound_community(&relay, &moved, &[]).await.unwrap_err();
        assert!(err.contains("was not served"), "a withheld control head aborts the refounding: {err}");
        assert_eq!(
            crate::db::community::load_community_v2(community.id()).unwrap().unwrap().root_epoch,
            Epoch(0),
            "the epoch did NOT advance (zero published state)"
        );
    }

    #[tokio::test]
    async fn refounding_rolls_the_root_and_severs_a_removed_member() {
        // CORD-06 §3: the owner re-founds, removing a member. The base root rolls, the
        // epoch advances, and the removed member's rekey-follow concludes they're cut.
        let (bed, owner, member) = TestBed::new();
        bed.swap_to(&owner);
        let community = create_community(&bed.relay, "Refound", bed.relays.clone(), None).await.unwrap();
        let bundle = bundle_of(&community, BundleAudience::Link, Some(owner.keys.public_key()), None, None);
        let bundle_json = serde_json::to_string(&bundle).unwrap();
        bed.swap_to(&member);
        let joined = accept_parked_invite(&bed.relay, &bundle_json, None).await.unwrap();

        bed.swap_to(&owner);
        let refounded = refound_community(&bed.relay, &community, &[member.keys.public_key()]).await.unwrap();
        assert_eq!(refounded.root_epoch, Epoch(1), "the epoch advanced");
        assert_ne!(refounded.community_root, community.community_root, "the base root rolled");
        // The owner still reads the compacted control plane at the new epoch.
        assert_eq!(
            crate::db::community::load_community_v2(community.id()).unwrap().unwrap().root_epoch,
            Epoch(1),
            "the owner committed the new epoch"
        );

        // The removed member, following rekeys, is severed (no blob in the rotation).
        // Guard captured AFTER the swap: it must belong to the ACTING account (the harness
        // swap now bumps the generation exactly like a production swap_session).
        bed.swap_to(&member);
        let session = crate::db::current_session();
        let follow = follow_rekeys(&bed.relay, &joined, &session).await.unwrap();
        assert!(follow.self_removed, "the removed member is cut by the re-founding");
    }

    #[tokio::test]
    async fn a_ban_holding_admin_can_re_found_but_not_evict_a_superior() {
        // CORD-06 §Authority: a Refounding requires BAN, not owner-identity. A
        // non-owner admin granted BAN CAN re-found (and every member follows it —
        // see the receive-side test), but the "strictly outrank every removed
        // target" rule still holds: they can't use it to evict the owner.
        let (bed, owner, member) = TestBed::new();
        bed.swap_to(&owner);
        let community = create_community(&bed.relay, "Guarded", bed.relays.clone(), None).await.unwrap();
        let rid = "b0".repeat(32);
        publish_role(&bed.relay, &community, &owner.keys, &admin_role(&rid, Permissions::BAN), 1).await;
        publish_grant(&bed.relay, &community, &owner.keys, &member.keys.public_key(), vec![rid], 1).await;
        let bundle = bundle_of(&community, BundleAudience::Link, Some(owner.keys.public_key()), None, None);
        let bundle_json = serde_json::to_string(&bundle).unwrap();
        bed.swap_to(&member);
        let joined = accept_parked_invite(&bed.relay, &bundle_json, None).await.unwrap();
        // Fold the roster so this member's own DB reflects their BAN grant (the
        // authority check reads the folded Roster, not the bundle).
        let _ = follow_control(&bed.relay, &joined).await;
        let joined = crate::db::community::load_community_v2(joined.id()).unwrap().unwrap();
        // Can't evict the owner (no one outranks the owner).
        assert!(refound_community(&bed.relay, &joined, &[owner.keys.public_key()]).await.is_err(), "a BAN-holder can't re-found to evict the owner");
        // But CAN re-found removing a plain member they outrank (here, nobody).
        assert!(refound_community(&bed.relay, &joined, &[]).await.is_ok(), "a BAN-holding admin can re-found");
    }

    #[tokio::test]
    async fn follow_rekeys_adopts_an_authorized_non_owner_base_rotation() {
        // A BAN-holding ADMIN (not the owner) re-founds, and every member must
        // follow it — owner-only receive silently strands members whose community
        // was refounded by an admin (CORD-06 §Authority: "a Refounding requires
        // BAN", checked against the folded Roster).
        let (bed, owner, me) = TestBed::new();
        let admin = Keys::generate();
        bed.swap_to(&owner);
        let community = create_community(&bed.relay, "AdminRefound", bed.relays.clone(), None).await.unwrap();
        let rid = "b0".repeat(32);
        publish_role(&bed.relay, &community, &owner.keys, &admin_role(&rid, Permissions::BAN), 1).await;
        publish_grant(&bed.relay, &community, &owner.keys, &admin.public_key(), vec![rid], 1).await;

        // I (a plain member) join, then fold the roster so I know the admin holds BAN.
        let bundle = bundle_of(&community, BundleAudience::Link, Some(owner.keys.public_key()), None, None);
        let bundle_json = serde_json::to_string(&bundle).unwrap();
        bed.swap_to(&me);
        let joined = accept_parked_invite(&bed.relay, &bundle_json, None).await.unwrap();
        let _ = follow_control(&bed.relay, &joined).await;
        let joined = crate::db::community::load_community_v2(joined.id()).unwrap().unwrap();

        // The admin re-founds keeping the owner + me — the owner must always be a
        // recipient of a non-owner Refounding.
        let new_root = [0xC7; 32];
        publish_base_rotation(&bed.relay, &joined, &admin, &[owner.keys.public_key(), me.keys.public_key()], &new_root, &joined.community_root).await;

        let updated = follow_rekeys(&bed.relay, &joined, &crate::db::current_session()).await.unwrap().updated
            .expect("an authorized admin's Refounding is adopted");
        assert_eq!(updated.root_epoch, Epoch(1), "advanced past the admin's rotation");
        assert_eq!(updated.community_root, new_root, "adopted the admin's fresh root");
    }

    #[tokio::test]
    async fn adopting_a_severing_rotation_revokes_my_own_links_instead_of_refreshing_them() {
        // The inverse of the sibling test: a SEVERING refound flips the stable-URL
        // contract. A raid arrives through the door, so every creator's client
        // buries its own links on adopt rather than carrying them into the new
        // epoch — which is the only way the OWNER's link dies when a bot admin ran
        // the containment (only the creator holds a link's signer secret).
        let (bed, owner, me) = TestBed::new();
        bed.swap_to(&owner);
        let community = create_community(&bed.relay, "SeverHeal", bed.relays.clone(), None).await.unwrap();
        let rid = "b1".repeat(32);
        publish_role(&bed.relay, &community, &owner.keys, &admin_role(&rid, Permissions::BAN | Permissions::CREATE_INVITE), 1).await;
        publish_grant(&bed.relay, &community, &owner.keys, &me.keys.public_key(), vec![rid], 1).await;

        let bundle = bundle_of(&community, BundleAudience::Link, Some(owner.keys.public_key()), None, None);
        let bundle_json = serde_json::to_string(&bundle).unwrap();
        bed.swap_to(&me);
        let joined = accept_parked_invite(&bed.relay, &bundle_json, None).await.unwrap();
        let _ = follow_control(&bed.relay, &joined).await;
        let joined = crate::db::community::load_community_v2(joined.id()).unwrap().unwrap();

        let minted = mint_public_link(&bed.relay, &joined, "https://x", None, None).await.unwrap();
        assert!(fetch_public_bundle(&bed.relay, &minted.url).await.is_ok(), "my link is live before the raid");

        // The owner runs a SEVERING refound (the raid lane).
        let new_root = [0xD5; 32];
        publish_severing_base_rotation(&bed.relay, &joined, &owner.keys, &[owner.keys.public_key(), me.keys.public_key()], &new_root, &joined.community_root).await;

        let updated = follow_rekeys(&bed.relay, &joined, &crate::db::current_session()).await.unwrap().updated
            .expect("the owner's severing Refounding is adopted");
        assert_eq!(updated.root_epoch, Epoch(1), "I still advance to the new epoch");

        let err = fetch_public_bundle(&bed.relay, &minted.url).await.unwrap_err();
        assert!(err.contains("revoked"), "my link must be a grave, not a refreshed door: {err}");
        assert!(
            crate::db::community::list_public_invites(&crate::simd::hex::bytes_to_hex_32(&updated.id().0)).unwrap().is_empty(),
            "and the local record goes with it",
        );
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn a_severing_adopt_never_deadlocks_the_last_link_creator() {
        // The severance runs INSIDE the follow, which holds `follow_lock` for the
        // whole call. `revoke_public_link`'s last-live-link escalation re-founds —
        // taking that same non-reentrant lock — so routing severance through it
        // would wedge this community's follow forever, for the very client whose
        // revocation empties the registry (typically the owner). The escalation-free
        // path is the fix; this test is its guard.
        let (bed, owner, me) = TestBed::new();
        bed.swap_to(&owner);
        let community = create_community(&bed.relay, "NoDeadlock", bed.relays.clone(), None).await.unwrap();
        let rid = "b2".repeat(32);
        publish_role(&bed.relay, &community, &owner.keys, &admin_role(&rid, Permissions::BAN | Permissions::CREATE_INVITE), 1).await;
        publish_grant(&bed.relay, &community, &owner.keys, &me.keys.public_key(), vec![rid], 1).await;
        let bundle = bundle_of(&community, BundleAudience::Link, Some(owner.keys.public_key()), None, None);
        let bundle_json = serde_json::to_string(&bundle).unwrap();
        bed.swap_to(&me);
        let joined = accept_parked_invite(&bed.relay, &bundle_json, None).await.unwrap();
        let _ = follow_control(&bed.relay, &joined).await;
        let joined = crate::db::community::load_community_v2(joined.id()).unwrap().unwrap();
        // My link is the ONLY one in the registry — revoking it empties the
        // aggregate, which is exactly the escalation's trigger condition.
        let minted = mint_public_link(&bed.relay, &joined, "https://x", None, None).await.unwrap();
        assert!(fetch_public_bundle(&bed.relay, &minted.url).await.is_ok());

        let new_root = [0xD6; 32];
        publish_severing_base_rotation(&bed.relay, &joined, &owner.keys, &[owner.keys.public_key(), me.keys.public_key()], &new_root, &joined.community_root).await;

        let followed = tokio::time::timeout(
            std::time::Duration::from_secs(20),
            follow_rekeys(&bed.relay, &joined, &crate::db::current_session()),
        )
        .await
        .expect("the severing follow must not deadlock on follow_lock")
        .unwrap();
        assert_eq!(followed.updated.expect("adopted").root_epoch, Epoch(1));
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn a_severing_adopt_spares_a_link_minted_after_the_raid() {
        // Severance is bounded by the rotation's own wire stamp, not "now". A
        // second device that adopts late must not eat the fresh link the owner
        // minted to re-open the community after the raid was over.
        let (bed, owner, me) = TestBed::new();
        bed.swap_to(&owner);
        let community = create_community(&bed.relay, "FreshDoor", bed.relays.clone(), None).await.unwrap();
        let rid = "b3".repeat(32);
        publish_role(&bed.relay, &community, &owner.keys, &admin_role(&rid, Permissions::BAN | Permissions::CREATE_INVITE), 1).await;
        publish_grant(&bed.relay, &community, &owner.keys, &me.keys.public_key(), vec![rid], 1).await;
        let bundle = bundle_of(&community, BundleAudience::Link, Some(owner.keys.public_key()), None, None);
        let bundle_json = serde_json::to_string(&bundle).unwrap();
        bed.swap_to(&me);
        let joined = accept_parked_invite(&bed.relay, &bundle_json, None).await.unwrap();
        let _ = follow_control(&bed.relay, &joined).await;
        let joined = crate::db::community::load_community_v2(joined.id()).unwrap().unwrap();
        let raid_era = mint_public_link(&bed.relay, &joined, "https://old", None, None).await.unwrap();

        let new_root = [0xD7; 32];
        publish_severing_base_rotation(&bed.relay, &joined, &owner.keys, &[owner.keys.public_key(), me.keys.public_key()], &new_root, &joined.community_root).await;
        let updated = follow_rekeys(&bed.relay, &joined, &crate::db::current_session()).await.unwrap().updated.expect("adopted");
        assert!(
            fetch_public_bundle(&bed.relay, &raid_era.url).await.unwrap_err().contains("revoked"),
            "the raid-era link is buried",
        );

        // The raid is over and the owner deliberately re-opens the community. The
        // pending-severance retry runs on every follow, so a door minted after the
        // containment must survive them all — otherwise no one could ever re-open.
        let fresh = mint_public_link(&bed.relay, &updated, "https://new", None, None).await.unwrap();
        let _ = follow_rekeys(&bed.relay, &updated, &crate::db::current_session()).await.unwrap();
        assert!(
            fetch_public_bundle(&bed.relay, &fresh.url).await.is_ok(),
            "a link minted after the containment survives later follow passes",
        );
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn an_unauthorized_severing_rotation_never_touches_my_links() {
        // The sever tag grants no authority of its own: it rides a rotation the
        // adopt gate has already verified. A plain member's forged severing
        // rotation is refused whole, so the tag is never even read.
        let (bed, owner, me) = TestBed::new();
        bed.swap_to(&owner);
        let community = create_community(&bed.relay, "NoForge", bed.relays.clone(), None).await.unwrap();
        let rid = "b4".repeat(32);
        publish_role(&bed.relay, &community, &owner.keys, &admin_role(&rid, Permissions::CREATE_INVITE), 1).await;
        publish_grant(&bed.relay, &community, &owner.keys, &me.keys.public_key(), vec![rid], 1).await;
        let bundle = bundle_of(&community, BundleAudience::Link, Some(owner.keys.public_key()), None, None);
        let bundle_json = serde_json::to_string(&bundle).unwrap();
        bed.swap_to(&me);
        let joined = accept_parked_invite(&bed.relay, &bundle_json, None).await.unwrap();
        let _ = follow_control(&bed.relay, &joined).await;
        let joined = crate::db::community::load_community_v2(joined.id()).unwrap().unwrap();
        let minted = mint_public_link(&bed.relay, &joined, "https://x", None, None).await.unwrap();

        // A stranger with no BAN mints a severing rotation.
        let stranger = Keys::generate();
        publish_severing_base_rotation(&bed.relay, &joined, &stranger, &[me.keys.public_key(), owner.keys.public_key()], &[0xD8; 32], &joined.community_root).await;

        let followed = follow_rekeys(&bed.relay, &joined, &crate::db::current_session()).await.unwrap();
        assert!(followed.updated.is_none(), "an unauthorized rotation is not adopted");
        assert!(fetch_public_bundle(&bed.relay, &minted.url).await.is_ok(), "and my link is untouched");
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn a_degraded_plane_read_is_not_evidence_of_absence() {
        // One honest relay is enough to RUN Concord — a sealed, signed rotation is
        // proof on its own. What one relay's silence is NOT enough for is concluding
        // a rotation does not exist. Those two cases used to be the same empty list,
        // so a client that could not reach anyone decided the community had simply
        // stopped rotating, and parked. Coverage is what separates them, and it is
        // measured against the REACHABLE set, so a single-relay community still gets
        // definitive answers.
        use crate::community::transport::adversarial::{AdversarialRelay, Fault, Match};
        let relay = AdversarialRelay::new();
        let (bed, owner, me) = TestBed::new();
        bed.swap_to(&owner);
        let community = create_community(relay.relay(), "Coverage", bed.relays.clone(), None).await.unwrap();
        let bundle = bundle_of(&community, BundleAudience::Link, Some(owner.keys.public_key()), None, None);
        let bundle_json = serde_json::to_string(&bundle).unwrap();
        bed.swap_to(&me);
        let joined = accept_parked_invite(relay.relay(), &bundle_json, None).await.unwrap();
        let _ = follow_control(relay.relay(), &joined).await;
        let joined = crate::db::community::load_community_v2(joined.id()).unwrap().unwrap();

        bed.swap_to(&owner);
        publish_base_rotation(relay.relay(), &joined, &owner.keys, &[owner.keys.public_key(), me.keys.public_key()], &[0xE9; 32], &joined.community_root).await;
        bed.swap_to(&me);

        // The plane cannot be reached at all: an Err, not an empty answer.
        let plane = base_rekey_group_key(&joined.community_root, joined.id(), Epoch(1));
        relay.on(Match::author(&plane.pk_hex()), Fault::FailFetch("relay down".into()));
        let _ = follow_rekeys(&relay, &joined, &crate::db::current_session()).await;
        let during = crate::db::community::load_community_v2(joined.id()).unwrap().unwrap();
        assert_eq!(
            during.root_epoch, joined.root_epoch,
            "an unreachable plane must not advance anything — but it must also not be \
             mistaken for a community that stopped rotating",
        );

        // The relay comes back. The rotation was there the whole time.
        relay.heal();
        let _ = follow_rekeys(&relay, &during, &crate::db::current_session()).await;
        let after = crate::db::community::load_community_v2(joined.id()).unwrap().unwrap();
        assert_eq!(
            after.root_epoch, Epoch(1),
            "once a relay answers, the rotation it was holding is adopted — the earlier \
             silence was never evidence",
        );
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn an_older_banlist_edition_can_never_un_ban() {
        // Un-banning is the fail-open direction: the un-banned party's rotations and
        // messages start being honored again. So a stale edition arriving late — a
        // slow relay, a replay, a re-fold under a narrowed window — must never
        // overwrite a newer list. Enforced at the storage layer so no future folding
        // change can reintroduce it.
        let (bed, owner, _me) = TestBed::new();
        bed.swap_to(&owner);
        let community = create_community(&bed.relay, "BanMonotonic", bed.relays.clone(), None).await.unwrap();
        let cid_hex = crate::simd::hex::bytes_to_hex_32(&community.id().0);
        let villain_keys = Keys::generate();
        let villain = villain_keys.public_key().to_hex();

        crate::db::community::set_community_banlist(&cid_hex, &[villain.clone()], 5).unwrap();
        assert!(crate::db::community::get_community_banlist(&cid_hex).unwrap().contains(&villain));

        // An OLDER edition (version 3) tries to replace it with an empty list.
        crate::db::community::set_community_banlist(&cid_hex, &[], 3).unwrap();
        assert!(
            crate::db::community::get_community_banlist(&cid_hex).unwrap().contains(&villain),
            "a lower-versioned edition must not un-ban",
        );
        assert!(
            crate::db::community::is_author_banned(&cid_hex, &villain_keys.public_key()),
            "and the hot cache must not hold the list we declined to persist",
        );

        // A NEWER edition legitimately un-bans.
        crate::db::community::set_community_banlist(&cid_hex, &[], 6).unwrap();
        assert!(
            !crate::db::community::is_author_banned(&cid_hex, &villain_keys.public_key()),
            "a newer edition still lifts a ban — monotonic, not frozen",
        );
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn a_withholding_relay_cannot_wipe_the_banlist_or_the_roster() {
        // Absence is not evidence. A relay that serves NO control editions folds an
        // empty aggregate, and an empty fold raises no gap flag — nothing is missing
        // from a window that contains nothing. Persisting that would un-ban every
        // banned member and strip every admin, locally, on one bad fetch. Un-banning
        // is the fail-OPEN direction: the un-banned party's rotations start being
        // honored again, which is how one client ends up on a branch minted by
        // someone everyone else has evicted.
        use crate::community::transport::adversarial::{AdversarialRelay, Fault, Match};
        let relay = AdversarialRelay::new();
        let (bed, owner, _me) = TestBed::new();
        bed.swap_to(&owner);
        let community = create_community(relay.relay(), "WitholdWipe", bed.relays.clone(), None).await.unwrap();
        let rid = "c4".repeat(32);
        let admin = Keys::generate();
        publish_role(relay.relay(), &community, &owner.keys, &admin_role(&rid, Permissions::BAN), 1).await;
        publish_grant(relay.relay(), &community, &owner.keys, &admin.public_key(), vec![rid], 1).await;
        let villain = Keys::generate();
        set_banlist(relay.relay(), &community, &[villain.public_key().to_hex()]).await.unwrap();
        let _ = follow_control(&relay, &community).await;

        let cid_hex = crate::simd::hex::bytes_to_hex_32(&community.id().0);
        assert!(
            crate::db::community::get_community_banlist(&cid_hex).unwrap().contains(&villain.public_key().to_hex()),
            "the ban folded",
        );
        let roster_before = crate::db::community::get_community_roles(&cid_hex).unwrap();
        assert!(!roster_before.grants.is_empty(), "the admin's grant folded");

        // Now the control plane serves nothing at all.
        let control_pk = control::ControlPlane::of(&community).pk_hex();
        relay.on(Match::author(&control_pk), Fault::Empty);
        let _ = follow_control(&relay, &community).await;

        assert!(
            crate::db::community::get_community_banlist(&cid_hex).unwrap().contains(&villain.public_key().to_hex()),
            "an empty control window must NEVER un-ban — that is the fail-open direction",
        );
        let roster_after = crate::db::community::get_community_roles(&cid_hex).unwrap();
        assert_eq!(
            roster_after.grants.len(), roster_before.grants.len(),
            "and must never strip standing: an empty fold is absence, not a demotion",
        );
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn a_banned_rotators_refounding_is_never_honored() {
        // Holding a key is never authority (CORD-06 §Authority). A member banned
        // moments ago still holds the current root, so they can mint a perfectly
        // shaped Refounding — right prev_commit, right epoch, real blobs. If a
        // client honors it, the banned party has just re-keyed the community around
        // itself and split every member who folded the ban from every member who
        // did not. The banlist has to be consulted at ADOPT time, not only at send.
        let (bed, owner, me) = TestBed::new();
        bed.swap_to(&owner);
        let community = create_community(&bed.relay, "BannedRotator", bed.relays.clone(), None).await.unwrap();
        let rid = "a9".repeat(32);
        publish_role(&bed.relay, &community, &owner.keys, &admin_role(&rid, Permissions::BAN), 1).await;
        let rogue = Keys::generate();
        publish_grant(&bed.relay, &community, &owner.keys, &rogue.public_key(), vec![rid], 1).await;
        let _ = follow_control(&bed.relay, &community).await;

        let bundle = bundle_of(&community, BundleAudience::Link, Some(owner.keys.public_key()), None, None);
        let bundle_json = serde_json::to_string(&bundle).unwrap();
        bed.swap_to(&me);
        let joined = accept_parked_invite(&bed.relay, &bundle_json, None).await.unwrap();
        let _ = follow_control(&bed.relay, &joined).await;
        let joined = crate::db::community::load_community_v2(joined.id()).unwrap().unwrap();

        // The rogue admin is banned, and we fold that ban.
        bed.swap_to(&owner);
        set_banlist(&bed.relay, &community, &[rogue.public_key().to_hex()]).await.unwrap();
        bed.swap_to(&me);
        let _ = follow_control(&bed.relay, &joined).await;
        let joined = crate::db::community::load_community_v2(joined.id()).unwrap().unwrap();
        let cid_hex = crate::simd::hex::bytes_to_hex_32(&joined.id().0);
        assert!(
            crate::db::community::get_community_banlist(&cid_hex).unwrap().contains(&rogue.public_key().to_hex()),
            "the ban folded before the rotation arrives",
        );

        // Still holding the root, the banned admin mints a Refounding anyway.
        bed.swap_to(&owner);
        publish_base_rotation(
            &bed.relay, &joined, &rogue,
            &[owner.keys.public_key(), me.keys.public_key(), rogue.public_key()],
            &[0xBA; 32], &joined.community_root,
        ).await;

        bed.swap_to(&me);
        let held_before = joined.root_epoch;
        let follow = follow_rekeys(&bed.relay, &joined, &crate::db::current_session()).await.unwrap();
        assert!(!follow.self_removed, "a banned rotator can never remove anyone");
        let after = crate::db::community::load_community_v2(joined.id()).unwrap().unwrap();
        assert_eq!(
            after.root_epoch, held_before,
            "a banned member's rotation must not move the epoch — honoring it hands the community to the party just evicted",
        );
        assert_eq!(after.community_root, joined.community_root, "and must not move the root");
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn a_rekey_exclusion_keeps_my_epoch_keys() {
        // Being removed must not cost me the ability to scrub my own history. The
        // epoch keys open no FUTURE epoch — post-removal keys are never delivered —
        // so retaining them leaks nothing; they are only what lets me author a 3305
        // self-delete of messages I already sent, each sealed under the epoch it was
        // sent at. Every other self-removal path retains them. The rekey-exclusion
        // path silently did not, so an eviction (or a false positive) destroyed that.
        let (bed, owner, me) = TestBed::new();
        bed.swap_to(&owner);
        let community = create_community(&bed.relay, "ExclusionKeys", bed.relays.clone(), None).await.unwrap();
        let bundle = bundle_of(&community, BundleAudience::Link, Some(owner.keys.public_key()), None, None);
        let bundle_json = serde_json::to_string(&bundle).unwrap();
        bed.swap_to(&me);
        let joined = accept_parked_invite(&bed.relay, &bundle_json, None).await.unwrap();
        let _ = follow_control(&bed.relay, &joined).await;
        let joined = crate::db::community::load_community_v2(joined.id()).unwrap().unwrap();
        let cid_hex = crate::simd::hex::bytes_to_hex_32(&joined.id().0);
        assert!(
            !crate::db::community::held_epoch_keys(&cid_hex, crate::community::SERVER_ROOT_SCOPE_HEX).unwrap().is_empty(),
            "the joiner archived its epoch key",
        );

        // The owner rotates and leaves me out — a genuine, authorized removal.
        bed.swap_to(&owner);
        publish_base_rotation(&bed.relay, &joined, &owner.keys, &[owner.keys.public_key()], &[0xD1; 32], &joined.community_root).await;

        bed.swap_to(&me);
        let follow = follow_rekeys(&bed.relay, &joined, &crate::db::current_session()).await.unwrap();
        assert!(follow.self_removed, "an authorized rotation that excluded me IS a removal");

        // The teardown the caller performs on self_removed.
        crate::db::community::delete_community_retain_keys(&cid_hex).unwrap();
        assert!(
            crate::db::community::load_community_v2(joined.id()).unwrap().is_none(),
            "the community is gone",
        );
        assert!(
            !crate::db::community::held_epoch_keys(&cid_hex, crate::community::SERVER_ROOT_SCOPE_HEX).unwrap().is_empty(),
            "but my epoch keys survive, so I can still self-delete what I wrote",
        );
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn a_client_that_adopted_the_losing_fork_converges_down_onto_the_canonical_one() {
        // Two authorized rotators mint the same epoch concurrently. The tiebreak is
        // deterministic — lowest new base key wins — but it only ever ran across
        // rotations seen in ONE fetch. A client that saw only the higher sibling
        // adopted it and then looked exclusively for its successor, so the canonical
        // branch became permanently unreachable: two halves of a community at the
        // same epoch number, different keys, unable to read each other, with nobody
        // misbehaving. Convergence has to be re-checked, not decided once.
        let (bed, owner, me) = TestBed::new();
        bed.swap_to(&owner);
        let community = create_community(&bed.relay, "ForkHeal", bed.relays.clone(), None).await.unwrap();
        let rid = "f1".repeat(32);
        publish_role(&bed.relay, &community, &owner.keys, &admin_role(&rid, Permissions::BAN), 1).await;
        publish_grant(&bed.relay, &community, &owner.keys, &me.keys.public_key(), vec![rid], 1).await;
        let bundle = bundle_of(&community, BundleAudience::Link, Some(owner.keys.public_key()), None, None);
        let bundle_json = serde_json::to_string(&bundle).unwrap();
        bed.swap_to(&me);
        let joined = accept_parked_invite(&bed.relay, &bundle_json, None).await.unwrap();
        let _ = follow_control(&bed.relay, &joined).await;
        let joined = crate::db::community::load_community_v2(joined.id()).unwrap().unwrap();

        // TWO rotators, which is what a real fork requires: rotations correlate on
        // (rotator, scope, epoch, prevcommit), so one rotator minting twice would
        // merge into a single rotation rather than fork — and `mint_or_reuse` stops
        // an honest rotator doing that anyway. A second BAN-holder is the genuine
        // concurrent-refound case. Low wins the spec's tiebreak.
        let rival = Keys::generate();
        bed.swap_to(&owner);
        publish_grant(&bed.relay, &community, &owner.keys, &rival.public_key(), vec!["f1".repeat(32)], 1).await;
        // The owner's client must fold the grant before minting the rival's rotation:
        // a non-owner rotation carries a `vac` citing the Grant it acts under, and an
        // uncited one is inadmissible by design.
        let _ = follow_control(&bed.relay, &community).await;
        bed.swap_to(&me);
        let _ = follow_control(&bed.relay, &joined).await;
        let joined = crate::db::community::load_community_v2(joined.id()).unwrap().unwrap();

        let low = [0x11u8; 32];
        let high = [0xF1u8; 32];
        let recipients = [owner.keys.public_key(), me.keys.public_key(), rival.public_key()];
        bed.swap_to(&owner);
        publish_base_rotation(&bed.relay, &joined, &owner.keys, &recipients, &high, &joined.community_root).await;

        // We see ONLY the high sibling first and adopt it — the fork is now set.
        bed.swap_to(&me);
        let session = crate::db::current_session();
        let _ = follow_rekeys(&bed.relay, &joined, &session).await.unwrap();
        let forked = crate::db::community::load_community_v2(joined.id()).unwrap().unwrap();
        assert_eq!(forked.root_epoch, Epoch(1), "adopted the sibling we could see");
        assert_eq!(forked.community_root, high, "and it is the LOSING branch");

        // The rival BAN-holder's sibling surfaces afterwards — a separate rotation,
        // and the one the deterministic tiebreak says everyone must land on.
        bed.swap_to(&owner);
        publish_base_rotation(&bed.relay, &joined, &rival, &recipients, &low, &joined.community_root).await;

        bed.swap_to(&me);
        let _ = follow_rekeys(&bed.relay, &forked, &session).await.unwrap();
        let healed = crate::db::community::load_community_v2(joined.id()).unwrap().unwrap();
        assert_eq!(
            healed.community_root, low,
            "a settled epoch MUST converge down onto the canonical sibling, or the community stays split",
        );
        assert_eq!(healed.root_epoch, Epoch(1), "same epoch — this is a sideways step, not an advance");

        // Down-only: re-running must not bounce back up to the higher sibling, or two
        // clients seeing the pair in different orders would oscillate forever.
        let _ = follow_rekeys(&bed.relay, &healed, &session).await.unwrap();
        let settled = crate::db::community::load_community_v2(joined.id()).unwrap().unwrap();
        assert_eq!(settled.community_root, low, "convergence is down-only and stable");
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn a_deep_catch_up_never_loses_ground_and_lands_on_the_head() {
        // The scenario this program exists for: a member returns after a community
        // rotated hard while they were away, on a link that keeps dropping.
        //
        // This asserts MONOTONICITY and CONVERGENCE — the epoch never moves
        // backward across passes, and the client ends exactly on the head, not one
        // short and not overshooting. Retention of a partial walk is a different
        // property with its own test (see the interrupted-mid-walk case, which fails
        // without per-hop banking); this one would still pass without banking, and
        // is not claiming otherwise.
        use crate::community::transport::adversarial::{AdversarialRelay, Fault, Match};
        const HOPS: u64 = 12;

        let relay = AdversarialRelay::new();
        let (bed, owner, me) = TestBed::new();
        bed.swap_to(&owner);
        let community = create_community(relay.relay(), "DeepStorm", bed.relays.clone(), None).await.unwrap();
        let bundle = bundle_of(&community, BundleAudience::Link, Some(owner.keys.public_key()), None, None);
        let bundle_json = serde_json::to_string(&bundle).unwrap();
        bed.swap_to(&me);
        let joined = accept_parked_invite(relay.relay(), &bundle_json, None).await.unwrap();
        let _ = follow_control(relay.relay(), &joined).await;
        let joined = crate::db::community::load_community_v2(joined.id()).unwrap().unwrap();

        // The community rotates HOPS times while we are offline. Owner-signed, so
        // authority is never the variable under test here — reachability is.
        bed.swap_to(&owner);
        let recipients = [owner.keys.public_key(), me.keys.public_key()];
        let mut cur = community.clone();
        let mut planes: Vec<String> = Vec::new();
        for i in 1..=HOPS {
            let root = [(0x40 + i) as u8; 32];
            planes.push(base_rekey_group_key(&cur.community_root, cur.id(), Epoch(i)).pk_hex());
            publish_base_rotation(relay.relay(), &cur, &owner.keys, &recipients, &root, &cur.community_root).await;
            cur.community_root = root;
            cur.root_epoch = Epoch(i);
        }

        // Come back into a storm. The failures are placed MID-WALK on purpose: each
        // pass gets several hops in before dying, so a walk that does not bank as it
        // goes loses a batch of work every time and can never get past the first
        // barrier. Failing only the first ask of each barrier means the link is
        // genuinely recovering, so the only question is whether progress survives.
        bed.swap_to(&me);
        for barrier in [5usize, 9] {
            relay.on(Match::author(&planes[barrier - 1]).nth(1), Fault::FailFetch("flaky link".into()));
        }

        let session = crate::db::current_session();
        let mut last = 0u64;
        // Bounded retries — the point is that each pass strictly advances, so a
        // finite number of them suffices however unlucky the link is.
        for pass in 0..(HOPS * 3) {
            let held = crate::db::community::load_community_v2(joined.id()).unwrap().unwrap();
            let now = held.root_epoch.0;
            assert!(
                now >= last,
                "pass {pass}: epoch went BACKWARD ({last} -> {now}); a catch-up must never lose ground",
            );
            last = now;
            if now == HOPS {
                break;
            }
            let _ = follow_rekeys(&relay, &held, &session).await;
        }

        let healed = crate::db::community::load_community_v2(joined.id()).unwrap().unwrap();
        assert_eq!(
            healed.root_epoch, Epoch(HOPS),
            "a deep backlog on a failing link must still converge on the head; stuck at {}",
            healed.root_epoch.0,
        );
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn a_missing_chunk_does_not_block_adopting_the_key_i_already_hold() {
        // Completeness gates ADOPTION today, not just removal. A 1,000-member
        // rotation spans thirteen chunks, so one unreachable chunk parks every
        // member of the community — including everyone whose key is sitting in a
        // chunk they already fetched and can open right now. Requiring the whole set
        // to adopt makes a large community's rotation as fragile as its worst chunk,
        // and the walk is sequential, so the strand blocks every epoch above it too.
        //
        // Completeness is required to conclude REMOVAL, which is destructive and
        // must stay conservative. Adoption is the safe direction: the blob is bound
        // to (scope, epoch) inside its ciphertext, so a key that opens is the key
        // for this rotation whatever else is missing.
        let (bed, owner, me) = TestBed::new();
        bed.swap_to(&owner);
        let community = create_community(&bed.relay, "PartialChunks", bed.relays.clone(), None).await.unwrap();
        let bundle = bundle_of(&community, BundleAudience::Link, Some(owner.keys.public_key()), None, None);
        let bundle_json = serde_json::to_string(&bundle).unwrap();
        bed.swap_to(&me);
        let joined = accept_parked_invite(&bed.relay, &bundle_json, None).await.unwrap();
        let _ = follow_control(&bed.relay, &joined).await;
        let joined = crate::db::community::load_community_v2(joined.id()).unwrap().unwrap();

        // A two-chunk rotation where only the chunk carrying MY blob is published.
        bed.swap_to(&owner);
        let new_root = [0xC7u8; 32];
        let new_epoch = Epoch(joined.root_epoch.0 + 1);
        let prev_commit = super::super::derive::epoch_key_commitment(joined.root_epoch, &joined.community_root);
        let group = base_rekey_group_key(&joined.community_root, joined.id(), new_epoch);
        let my_blob = rekey::build_blob_local(
            owner.keys.secret_key(), &owner.keys.public_key().to_bytes(),
            &me.keys.public_key(), RekeyScope::Root, new_epoch, &new_root,
        ).unwrap();
        // Declares 2 chunks; only chunk 1 ever reaches the relay.
        let rumor = rekey::build_rekey_rumor(
            owner.keys.public_key(), RekeyScope::Root, new_epoch, joined.root_epoch,
            &prev_commit, &[my_blob], 1, 2, 2_000,
            my_authority_citation(&joined, &owner.keys.public_key()).as_ref(), false,
        ).unwrap();
        let (wrap, _) = rekey::seal_rekey_chunk(&rumor, &group, &owner.keys, Timestamp::from_secs(2_000)).unwrap();
        bed.relay.publish(&wrap, &bed.relays).await.unwrap();

        bed.swap_to(&me);
        let follow = follow_rekeys(&bed.relay, &joined, &crate::db::current_session()).await.unwrap();
        assert!(!follow.self_removed, "a missing chunk is never a removal");
        let after = crate::db::community::load_community_v2(joined.id()).unwrap().unwrap();
        assert_eq!(
            after.root_epoch, new_epoch,
            "my blob was present and opened — the missing sibling chunk says nothing about MY key, \
             and parking here strands the whole community behind its least reachable chunk",
        );
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn an_empty_rotation_is_never_a_mass_removal() {
        // `is_complete` is satisfied by a single chunk declaring n=1 — including one
        // carrying ZERO blobs, which the builders emit verbatim for an empty
        // recipient set. Read literally that is "a complete, authorized rotation
        // containing no blob for me", i.e. removal — and the removal path DELETES the
        // community locally, keys and all. From the owner, one such rotation would
        // evict every member of the community at once, irreversibly.
        //
        // Nobody can be removed by a rotation that removed everybody.
        let (bed, owner, me) = TestBed::new();
        bed.swap_to(&owner);
        let community = create_community(&bed.relay, "EmptyRotation", bed.relays.clone(), None).await.unwrap();
        let bundle = bundle_of(&community, BundleAudience::Link, Some(owner.keys.public_key()), None, None);
        let bundle_json = serde_json::to_string(&bundle).unwrap();
        bed.swap_to(&me);
        let joined = accept_parked_invite(&bed.relay, &bundle_json, None).await.unwrap();
        let _ = follow_control(&bed.relay, &joined).await;
        let joined = crate::db::community::load_community_v2(joined.id()).unwrap().unwrap();

        // The owner publishes a complete rotation with no recipients at all.
        bed.swap_to(&owner);
        publish_base_rotation(&bed.relay, &joined, &owner.keys, &[], &[0xB0; 32], &joined.community_root).await;

        bed.swap_to(&me);
        let follow = follow_rekeys(&bed.relay, &joined, &crate::db::current_session()).await.unwrap();
        assert!(
            !follow.self_removed,
            "an all-empty rotation must NEVER read as my removal — that path deletes the community",
        );
        assert!(
            crate::db::community::load_community_v2(joined.id()).unwrap().is_some(),
            "and the community must still be held",
        );
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn a_catch_up_interrupted_mid_walk_keeps_the_hops_it_already_took() {
        // A client back from a week offline walks many epochs in one pass. Today the
        // community row is written ONCE, after the loop, so a fetch failure on the
        // last hop discards every hop already walked — the next attempt starts from
        // zero, costs the same again, and on a flaky link may never converge at all.
        // Progress must be banked per hop.
        use crate::community::transport::adversarial::{AdversarialRelay, Fault, Match};
        // The bed supplies isolated per-account DBs; the adversarial relay replaces
        // its transport so a fault plan governs what the client can read back.
        let relay = AdversarialRelay::new();
        let (bed, owner, me) = TestBed::new();
        bed.swap_to(&owner);
        let community = create_community(relay.relay(), "DeepCatchUp", bed.relays.clone(), None).await.unwrap();

        let bundle = bundle_of(&community, BundleAudience::Link, Some(owner.keys.public_key()), None, None);
        let bundle_json = serde_json::to_string(&bundle).unwrap();
        bed.swap_to(&me);
        let joined = accept_parked_invite(relay.relay(), &bundle_json, None).await.unwrap();
        let _ = follow_control(relay.relay(), &joined).await;
        let joined = crate::db::community::load_community_v2(joined.id()).unwrap().unwrap();

        // Owner rotates three times while we are away. Owner rotations need no roster.
        bed.swap_to(&owner);
        let mut cur = community.clone();
        let roots = [[0xA1u8; 32], [0xA2; 32], [0xA3; 32]];
        let recipients = [owner.keys.public_key(), me.keys.public_key()];
        for (i, root) in roots.iter().enumerate() {
            publish_base_rotation(relay.relay(), &cur, &owner.keys, &recipients, root, &cur.community_root).await;
            cur.community_root = *root;
            cur.root_epoch = Epoch(i as u64 + 1);
        }

        // Come back, but the plane for the LAST hop is unreachable.
        bed.swap_to(&me);
        let third_hop = base_rekey_group_key(&roots[1], joined.id(), Epoch(3));
        relay.on(Match::author(&third_hop.pk_hex()), Fault::FailFetch("relay dropped".into()));

        let _ = follow_rekeys(&relay, &joined, &crate::db::current_session()).await;

        let after = crate::db::community::load_community_v2(joined.id()).unwrap().unwrap();
        assert!(
            after.root_epoch.0 >= 2,
            "hops 1 and 2 succeeded and MUST be banked; an interrupted walk that reverts to epoch {} \
             restarts from scratch every attempt and may never converge on a flaky link",
            after.root_epoch.0,
        );

        // Faults cease: the walk resumes from where it banked and reaches the head.
        relay.heal();
        let _ = follow_rekeys(&relay, &after, &crate::db::current_session()).await;
        let healed = crate::db::community::load_community_v2(joined.id()).unwrap().unwrap();
        assert_eq!(healed.root_epoch, Epoch(3), "once faults cease the walk converges on the head");
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn a_promote_is_reported_as_an_authority_change() {
        // The single line whose absence was the fork. A promote moves the ROSTER,
        // which lives in its own column and never appears in the returned document —
        // so a caller keying its retry off `updated` alone sees "nothing happened",
        // skips the re-walk, and leaves the rekey pass that just refused this admin's
        // rotation to never reconsider it. Asserted at the unit level deliberately:
        // an integration drill can pass for the wrong reason (a roster cached on some
        // earlier pass), and this codebase has been bitten by exactly that before.
        let (bed, owner, admin) = TestBed::new();
        bed.swap_to(&owner);
        let community = create_community(&bed.relay, "PromoteReports", bed.relays.clone(), None).await.unwrap();
        follow_control(&bed.relay, &community).await.unwrap(); // settle the baseline

        let rid = "e1".repeat(32);
        publish_role(&bed.relay, &community, &owner.keys, &admin_role(&rid, Permissions::BAN), 1).await;
        publish_grant(&bed.relay, &community, &owner.keys, &admin.keys.public_key(), vec![rid], 1).await;

        let control = follow_control(&bed.relay, &community).await.unwrap();
        assert!(
            control.authority_changed,
            "a promote MUST report an authority change — this is what re-runs the rekey walk",
        );
        assert!(control.moved(), "and therefore counts as movement");
        assert!(
            control.updated.is_none(),
            "while moving no document at all — which is precisely why `updated` alone was blind",
        );
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn a_seeded_roster_never_vetoes_a_coherent_control_fold() {
        // `merge_local_roster` seeds an optimistic roster at `roles_at = 0` so a
        // just-created role works before its edition folds. That seed names entities
        // the plane may never head, which made `stored_complete` false FOREVER — the
        // roster could never be replaced, and a roster that never updates cannot
        // authorize anyone, so the client silently refused every rotation that admin
        // published. It landed on owners, who seed the most.
        let (bed, owner, admin) = TestBed::new();
        bed.swap_to(&owner);
        let community = create_community(&bed.relay, "SeedVeto", bed.relays.clone(), None).await.unwrap();
        let cid_hex = crate::simd::hex::bytes_to_hex_32(&community.id().0);
        let rid = "c1".repeat(32);
        publish_role(&bed.relay, &community, &owner.keys, &admin_role(&rid, Permissions::BAN), 1).await;
        publish_grant(&bed.relay, &community, &owner.keys, &admin.keys.public_key(), vec![rid], 1).await;

        // A seed naming an entity the plane will never head, with NO provenance —
        // exactly what creating a private channel leaves behind.
        let ghost = "d4".repeat(32);
        let mut seeded = crate::community::roles::CommunityRoles::default();
        seeded.roles.push(admin_role(&ghost, Permissions::MANAGE_CHANNELS));
        seeded.grants.push(crate::community::roles::MemberGrant {
            member: owner.keys.public_key().to_hex(),
            role_ids: vec![ghost.clone()],
        });
        crate::db::community::set_community_roles(&cid_hex, &seeded, 0).unwrap();
        // A floor for the ghost is what turns `stored_complete` false.
        crate::db::community::set_edition_head_at_epoch(&cid_hex, &ghost, 1, &[0u8; 32], &[0u8; 32], community.root_epoch.0).unwrap();

        follow_control(&bed.relay, &community).await.unwrap().updated;

        let folded = crate::db::community::get_community_roles(&cid_hex).unwrap();
        assert!(
            folded.grants.iter().any(|g| g.member == admin.keys.public_key().to_hex()),
            "a coherent fold must replace a provenance-less seed, or the client is deaf to this admin forever",
        );
        assert_ne!(
            crate::db::community::get_community_roles_at(&cid_hex).unwrap(),
            0,
            "and the replacement carries the plane's provenance",
        );
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn a_pending_severance_heals_on_a_quiet_follow_pass() {
        // The retry must run on passes that adopt NOTHING. A one-shot transport
        // blip during the original severance otherwise has no healing trigger
        // until some future rotation happens to be adopted — and until then the
        // community reads Public, which silently strips the refound from every
        // ordinary ban.
        let (bed, owner, me) = TestBed::new();
        bed.swap_to(&owner);
        let community = create_community(&bed.relay, "QuietHeal", bed.relays.clone(), None).await.unwrap();
        let rid = "b5".repeat(32);
        publish_role(&bed.relay, &community, &owner.keys, &admin_role(&rid, Permissions::BAN | Permissions::CREATE_INVITE), 1).await;
        publish_grant(&bed.relay, &community, &owner.keys, &me.keys.public_key(), vec![rid], 1).await;
        let bundle = bundle_of(&community, BundleAudience::Link, Some(owner.keys.public_key()), None, None);
        let bundle_json = serde_json::to_string(&bundle).unwrap();
        bed.swap_to(&me);
        let joined = accept_parked_invite(&bed.relay, &bundle_json, None).await.unwrap();
        let _ = follow_control(&bed.relay, &joined).await;
        let joined = crate::db::community::load_community_v2(joined.id()).unwrap().unwrap();
        let minted = mint_public_link(&bed.relay, &joined, "https://x", None, None).await.unwrap();

        // A containment was adopted but its revoke was interrupted: the mark is
        // down, the epoch-0 link still stands.
        let cid_hex = crate::simd::hex::bytes_to_hex_32(&joined.id().0);
        add_sever_mark(&cid_hex, 1, 5_000);
        assert!(fetch_public_bundle(&bed.relay, &minted.url).await.is_ok());

        // A QUIET follow — no rotation anywhere — must finish the burial.
        let followed = follow_rekeys(&bed.relay, &joined, &crate::db::current_session()).await.unwrap();
        assert!(followed.updated.is_none(), "nothing to adopt");
        assert!(
            fetch_public_bundle(&bed.relay, &minted.url).await.unwrap_err().contains("revoked"),
            "the interrupted severance healed with no rotation to carry it",
        );
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn a_sever_survives_a_later_ordinary_rotation_in_the_same_walk() {
        // Sticky severance: a client catching up walks EVERY missed rotation in
        // one pass. If the containment hop is followed by an ordinary one,
        // last-hop-wins semantics would refresh the links right back open — the
        // door the raid came through, re-armed with the newest root.
        let (bed, owner, me) = TestBed::new();
        bed.swap_to(&owner);
        let community = create_community(&bed.relay, "StickySever", bed.relays.clone(), None).await.unwrap();
        let rid = "b6".repeat(32);
        publish_role(&bed.relay, &community, &owner.keys, &admin_role(&rid, Permissions::BAN | Permissions::CREATE_INVITE), 1).await;
        publish_grant(&bed.relay, &community, &owner.keys, &me.keys.public_key(), vec![rid], 1).await;
        let bundle = bundle_of(&community, BundleAudience::Link, Some(owner.keys.public_key()), None, None);
        let bundle_json = serde_json::to_string(&bundle).unwrap();
        bed.swap_to(&me);
        let joined = accept_parked_invite(&bed.relay, &bundle_json, None).await.unwrap();
        let _ = follow_control(&bed.relay, &joined).await;
        let joined = crate::db::community::load_community_v2(joined.id()).unwrap().unwrap();
        let minted = mint_public_link(&bed.relay, &joined, "https://x", None, None).await.unwrap();

        // Hop 1: the containment. Hop 2: an ordinary rotation on top of it.
        let root1 = [0xE1; 32];
        publish_severing_base_rotation(&bed.relay, &joined, &owner.keys, &[owner.keys.public_key(), me.keys.public_key()], &root1, &joined.community_root).await;
        let mut stepped = joined.clone();
        stepped.community_root = root1;
        stepped.root_epoch = Epoch(1);
        let root2 = [0xE2; 32];
        publish_base_rotation(&bed.relay, &stepped, &owner.keys, &[owner.keys.public_key(), me.keys.public_key()], &root2, &root1).await;

        let updated = follow_rekeys(&bed.relay, &joined, &crate::db::current_session()).await.unwrap().updated.expect("both hops adopt");
        assert_eq!(updated.root_epoch, Epoch(2), "the walk reached the ordinary head");
        assert!(
            fetch_public_bundle(&bed.relay, &minted.url).await.unwrap_err().contains("revoked"),
            "the containment's burial survived the ordinary hop behind it",
        );
    }

    /// Did the severing refound vend `who` a key? Opens the base rotation and looks
    /// for a blob at their locator.
    async fn vended_to(bed: &TestBed, before: &CommunityV2, who: &Keys) -> bool {
        let next = Epoch(before.root_epoch.0 + 1);
        let group = base_rekey_group_key(&before.community_root, before.id(), next);
        let chunks = fetch_rekey_chunks(&bed.relay, &before.relays, &group).await.unwrap();
        rekey::collect_rotations(&chunks).iter().any(|r| {
            rekey::find_my_blobs(
                &r.blobs,
                &r.rotator.to_bytes(),
                &who.public_key().to_bytes(),
                RekeyScope::Root,
                next,
            )
            .next()
            .is_some()
        })
    }

    /// Local guestbook row for `who`, claiming `at_ms` but OBSERVED at `seen`.
    fn local_join_observed(who: &Keys, at_ms: u64, seen: u64, epoch: u64, tag: u8) -> guestbook::GuestbookEvent {
        guestbook::GuestbookEvent {
            rumor_id: [tag; 32],
            entry: guestbook::GuestbookEntry::Join { member: who.public_key(), invited_by: None, at_ms },
            epoch: Some(epoch),
            observed_at: Some(seen),
        }
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn a_backdated_join_cannot_slide_under_the_window_when_we_watched_it_arrive() {
        // `at_ms` is author-claimed, so a raider can put it a year in the past and pass
        // any window computed from the claim alone. What this client WATCHED arrive is
        // not theirs to write.
        let (bed, owner, _o) = TestBed::new();
        bed.swap_to(&owner);
        let community = create_community(&bed.relay, "Backdate", bed.relays.clone(), None).await.unwrap();
        let cid_hex = crate::simd::hex::bytes_to_hex_32(&community.id().0);
        let liar = Keys::generate();

        // Claims it joined long before the window; we saw it arrive INSIDE the window.
        let gb = super::super::derive::guestbook_group_key(&community.community_root, community.id(), community.root_epoch);
        let join = guestbook::build_join_rumor(liar.public_key(), None, 1_000);
        let (wrap, _) = guestbook::seal_guestbook_rumor(&join, &gb, &liar, Timestamp::from_secs(1)).unwrap();
        bed.relay.publish(&wrap, &bed.relays).await.unwrap();
        crate::db::community::set_guestbook(&cid_hex, &[local_join_observed(&liar, 1_000, 9_000, community.root_epoch.0, 3)], 0).unwrap();
        // We were following well before the window opened.
        crate::db::settings::set_sql_setting(format!("gb_observed_since:{cid_hex}"), "100".into()).unwrap();

        refound_community_severing(&bed.relay, &community, &[], 5_000).await.unwrap();

        assert!(
            !vended_to(&bed, &community, &liar).await,
            "a backdated Join must not beat the arrival we watched with our own clock",
        );
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn a_client_that_started_watching_late_evicts_nobody() {
        // Same row, same claim, same observation — but this client only began following
        // the guestbook AFTER the window opened, so everything looks new to it. Its
        // observations prove nothing, and acting on them would evict the community.
        let (bed, owner, _o) = TestBed::new();
        bed.swap_to(&owner);
        let community = create_community(&bed.relay, "LateWatcher", bed.relays.clone(), None).await.unwrap();
        let cid_hex = crate::simd::hex::bytes_to_hex_32(&community.id().0);
        let quiet = Keys::generate();

        let gb = super::super::derive::guestbook_group_key(&community.community_root, community.id(), community.root_epoch);
        let join = guestbook::build_join_rumor(quiet.public_key(), None, 1_000);
        let (wrap, _) = guestbook::seal_guestbook_rumor(&join, &gb, &quiet, Timestamp::from_secs(1)).unwrap();
        bed.relay.publish(&wrap, &bed.relays).await.unwrap();
        crate::db::community::set_guestbook(&cid_hex, &[local_join_observed(&quiet, 1_000, 9_000, community.root_epoch.0, 4)], 0).unwrap();
        // Coverage begins INSIDE the window — we were not here before it.
        crate::db::settings::set_sql_setting(format!("gb_observed_since:{cid_hex}"), "7000".into()).unwrap();

        refound_community_severing(&bed.relay, &community, &[], 5_000).await.unwrap();

        assert!(
            vended_to(&bed, &community, &quiet).await,
            "without coverage predating the window our observations prove nothing — an \
             old member must not be evicted for having been noticed late",
        );
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn a_purge_vends_only_to_the_retain_list_however_late_a_stranger_arrives() {
        // The Admin Terminal hands over a RETAIN list. Internally that used to become a
        // removal list computed from the memberlist at one instant, while the refound
        // fetched its own later — so an account appearing in between was on neither
        // list and got a key by DEFAULT, implicitly retained by the purge meant to be
        // exhaustive. An allow-list closes it with no window and nothing to backdate.
        let (bed, owner, _o) = TestBed::new();
        bed.swap_to(&owner);
        let community = create_community(&bed.relay, "Purge", bed.relays.clone(), None).await.unwrap();
        let kept = Keys::generate();
        let stranger = Keys::generate();
        let gb = super::super::derive::guestbook_group_key(&community.community_root, community.id(), community.root_epoch);
        // The stranger even BACKDATES their Join — an allow-list does not care.
        for (who, at_ms) in [(&kept, 2_000_000u64), (&stranger, 1_000u64)] {
            let join = guestbook::build_join_rumor(who.public_key(), None, at_ms);
            let (wrap, _) = guestbook::seal_guestbook_rumor(&join, &gb, who, Timestamp::from_secs(at_ms / 1000)).unwrap();
            bed.relay.publish(&wrap, &bed.relays).await.unwrap();
        }

        // The operator selected exactly one member. Nobody named the stranger.
        refound_community_retaining(&bed.relay, &community, &[], &[kept.public_key()]).await.unwrap();

        assert!(
            vended_to(&bed, &community, &kept).await,
            "the selected member keeps their key",
        );
        assert!(
            !vended_to(&bed, &community, &stranger).await,
            "an account not on the retain list is vended NO key, no matter when it \
             appeared or what Join time it claims",
        );
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn a_raid_window_joiner_is_vended_no_key_even_if_nobody_named_them() {
        // The recipient set is a LIVE fetch taken AFTER the cut was computed, and
        // re-taken on every retry. A bot arriving in that gap is in the memberlist and
        // absent from the cut — and was handed a working key for the very epoch meant
        // to evict it. Testing join TIME catches it with nobody naming it.
        let (bed, owner, _o) = TestBed::new();
        bed.swap_to(&owner);
        let community = create_community(&bed.relay, "RaceCut", bed.relays.clone(), None).await.unwrap();
        let established = Keys::generate();
        let late = Keys::generate();
        let gb = super::super::derive::guestbook_group_key(&community.community_root, community.id(), community.root_epoch);
        for (who, at_ms) in [(&established, 2_000_000u64), (&late, 9_000_000)] {
            let join = guestbook::build_join_rumor(who.public_key(), None, at_ms);
            let (wrap, _) = guestbook::seal_guestbook_rumor(&join, &gb, who, Timestamp::from_secs(at_ms / 1000)).unwrap();
            bed.relay.publish(&wrap, &bed.relays).await.unwrap();
        }

        // Window opens at 5_000s. `late` is named by NOBODY — the cut is empty.
        refound_community_severing(&bed.relay, &community, &[], 5_000).await.unwrap();

        assert!(
            !vended_to(&bed, &community, &late).await,
            "a raid-window joiner must be vended NO key, even when nobody named them",
        );
        assert!(
            vended_to(&bed, &community, &established).await,
            "and the member who was already here keeps theirs",
        );
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn a_member_whose_join_is_not_on_the_plane_is_never_read_as_a_late_joiner() {
        // THE regression that matters. A quiet member's Join lives on a buried epoch,
        // so the reachable guestbook has no trace of them at all. Absence must read as
        // OLD, never as new — reading it the other way shed 39 real members across five
        // rotations. Here the Join exists ONLY locally, exactly as a buried one does.
        let (bed, owner, _o) = TestBed::new();
        bed.swap_to(&owner);
        let community = create_community(&bed.relay, "Buried", bed.relays.clone(), None).await.unwrap();
        let cid_hex = crate::simd::hex::bytes_to_hex_32(&community.id().0);
        let quiet = Keys::generate();
        let local_join = guestbook::GuestbookEvent {
            rumor_id: [7u8; 32],
            entry: guestbook::GuestbookEntry::Join { member: quiet.public_key(), invited_by: None, at_ms: 9_900_000 },
            epoch: Some(community.root_epoch.0),
            observed_at: None,
        };
        crate::db::community::set_guestbook(&cid_hex, &[local_join], 0).unwrap();

        // Even stamped INSIDE the window, a Join the plane does not serve must not evict.
        refound_community_severing(&bed.relay, &community, &[], 5_000).await.unwrap();

        assert!(
            vended_to(&bed, &community, &quiet).await,
            "no Join on the reachable plane means OLD — absence of evidence must never evict",
        );
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn contain_raid_bans_cuts_and_severs_end_to_end() {
        let (bed, owner, _other) = TestBed::new();
        bed.swap_to(&owner);
        let community = create_community(&bed.relay, "Containment", bed.relays.clone(), None).await.unwrap();
        let minted = mint_public_link(&bed.relay, &community, "https://x", None, None).await.unwrap();

        // Three arrivals: an established member (before the window), a convicted
        // raider and a quiet lurker (both inside it).
        let established = Keys::generate();
        let raider = Keys::generate();
        let lurker = Keys::generate();
        let gb = super::super::derive::guestbook_group_key(&community.community_root, community.id(), community.root_epoch);
        for (who, at_ms) in [(&established, 2_000_000u64), (&raider, 9_000_000), (&lurker, 9_500_000)] {
            let join = guestbook::build_join_rumor(who.public_key(), None, at_ms);
            let (wrap, _) = guestbook::seal_guestbook_rumor(&join, &gb, who, Timestamp::from_secs(at_ms / 1000)).unwrap();
            bed.relay.publish(&wrap, &bed.relays).await.unwrap();
        }

        let report = contain_raid(&bed.relay, community.id(), &[raider.public_key()], 5_000, &[]).await.unwrap();
        assert_eq!(report.banned, 1, "the convicted raider is banned");
        assert_eq!(report.window_cut, 1, "the lurker who joined inside the window is cut");
        assert!(report.refound_ok, "the severing refound landed: {:?}", report.warnings);
        assert_eq!((report.epoch_before, report.epoch_after), (0, 1), "the root rolled");
        assert_eq!(report.own_links_revoked, 1, "the door closed with it");

        let cid_hex = crate::simd::hex::bytes_to_hex_32(&community.id().0);
        let banlist = crate::db::community::get_community_banlist(&cid_hex).unwrap();
        assert!(banlist.contains(&raider.public_key().to_hex()), "raider on the banlist");
        assert!(!banlist.contains(&lurker.public_key().to_hex()), "the lurker is cut, never banned — they can rejoin through a fresh link");
        assert!(!banlist.contains(&established.public_key().to_hex()));
        assert!(
            fetch_public_bundle(&bed.relay, &minted.url).await.unwrap_err().contains("revoked"),
            "the invite URL the raid used is a grave",
        );

        // The rotation's recipient set is the severance line: the established
        // member rides into the new epoch, the raider and the lurker do not.
        let updated = crate::db::community::load_community_v2(community.id()).unwrap().unwrap();
        assert_eq!(updated.root_epoch, Epoch(1));
        let members = memberlist(&bed.relay, &updated).await.unwrap();
        assert!(members.contains(&established.public_key()), "established member survives");
        assert!(!members.contains(&raider.public_key()), "raider gone");
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn adopting_someone_elses_rotation_refreshes_my_own_live_links() {
        // CORD-05 §2: a link shared once keeps working across rotations, because
        // its bundle is re-posted behind the same URL. The Refounder can only
        // refresh the bundles they hold signer secrets for — their OWN — so
        // every other creator has to heal their links when they ADOPT the
        // rotation. Without that, an admin's links keep vending the superseded
        // root and drop new joiners onto a dead epoch, which is precisely the
        // stranding the stable-URL refresh exists to prevent.
        let (bed, owner, me) = TestBed::new();
        bed.swap_to(&owner);
        let community = create_community(&bed.relay, "LinkHeal", bed.relays.clone(), None).await.unwrap();
        let rid = "b1".repeat(32);
        // CREATE_INVITE too: minting is offer-gated by the same bit readers use.
        publish_role(&bed.relay, &community, &owner.keys, &admin_role(&rid, Permissions::BAN | Permissions::CREATE_INVITE), 1).await;
        publish_grant(&bed.relay, &community, &owner.keys, &me.keys.public_key(), vec![rid], 1).await;

        let bundle = bundle_of(&community, BundleAudience::Link, Some(owner.keys.public_key()), None, None);
        let bundle_json = serde_json::to_string(&bundle).unwrap();
        bed.swap_to(&me);
        let joined = accept_parked_invite(&bed.relay, &bundle_json, None).await.unwrap();
        let _ = follow_control(&bed.relay, &joined).await;
        let joined = crate::db::community::load_community_v2(joined.id()).unwrap().unwrap();

        // I mint a link of my own at the CURRENT epoch.
        let minted = mint_public_link(&bed.relay, &joined, "https://x", None, None).await.unwrap();
        let vended_before = fetch_public_bundle(&bed.relay, &minted.url).await.unwrap();
        assert_eq!(vended_before.root_epoch, 0, "my link vends the epoch I minted it at");

        // The OWNER re-founds. Their refresh can't touch my bundle: only I hold
        // its signer secret.
        let new_root = [0xD4; 32];
        publish_base_rotation(&bed.relay, &joined, &owner.keys, &[owner.keys.public_key(), me.keys.public_key()], &new_root, &joined.community_root).await;

        let updated = follow_rekeys(&bed.relay, &joined, &crate::db::current_session()).await.unwrap().updated
            .expect("the owner's Refounding is adopted");
        assert_eq!(updated.root_epoch, Epoch(1), "I advanced to the new epoch");

        let vended_after = fetch_public_bundle(&bed.relay, &minted.url).await.unwrap();
        assert_eq!(vended_after.root_epoch, 1, "my link must now vend the NEW epoch, not strand its joiners");
        assert_eq!(
            crate::simd::hex::hex_to_bytes_32(&vended_after.community_root),
            new_root,
            "and the new root behind the same URL",
        );
    }

    #[tokio::test]
    async fn follow_rekeys_refuses_a_refounding_that_excludes_the_owner() {
        // Authority escalation: a BAN-admin can't use a Refounding to evict the
        // OWNER (no one outranks the owner). Excluding them makes the rotation
        // inadmissible — members fork-reject it rather than migrate to the coup.
        let (bed, owner, me) = TestBed::new();
        let admin = Keys::generate();
        bed.swap_to(&owner);
        let community = create_community(&bed.relay, "NoCoup", bed.relays.clone(), None).await.unwrap();
        let rid = "b0".repeat(32);
        publish_role(&bed.relay, &community, &owner.keys, &admin_role(&rid, Permissions::BAN), 1).await;
        publish_grant(&bed.relay, &community, &owner.keys, &admin.public_key(), vec![rid], 1).await;

        let bundle = bundle_of(&community, BundleAudience::Link, Some(owner.keys.public_key()), None, None);
        let bundle_json = serde_json::to_string(&bundle).unwrap();
        bed.swap_to(&me);
        let joined = accept_parked_invite(&bed.relay, &bundle_json, None).await.unwrap();
        let _ = follow_control(&bed.relay, &joined).await;
        let joined = crate::db::community::load_community_v2(joined.id()).unwrap().unwrap();

        // The admin re-founds delivering to me but NOT the owner — a takeover.
        publish_base_rotation(&bed.relay, &joined, &admin, &[me.keys.public_key()], &[0xEE; 32], &joined.community_root).await;
        let follow = follow_rekeys(&bed.relay, &joined, &crate::db::current_session()).await.unwrap();
        assert!(follow.updated.is_none() && !follow.self_removed, "an owner-excluding Refounding is not adopted");
    }

    #[tokio::test]
    async fn follow_rekeys_refuses_a_refounding_that_excludes_a_peer_admin() {
        // Authority escalation: two equal-rank BAN-admins — neither strictly
        // outranks the other, so one can't Refound the other out. Excluding a
        // peer makes the rotation inadmissible.
        let (bed, owner, me) = TestBed::new();
        let admin_a = Keys::generate();
        let admin_b = Keys::generate(); // the peer admin the rotation excludes.
        bed.swap_to(&owner);
        let community = create_community(&bed.relay, "Peers", bed.relays.clone(), None).await.unwrap();
        let rid = "b0".repeat(32);
        publish_role(&bed.relay, &community, &owner.keys, &admin_role(&rid, Permissions::BAN), 1).await;
        // Both A and B hold the SAME role (same position 1) → peers.
        publish_grant(&bed.relay, &community, &owner.keys, &admin_a.public_key(), vec![rid.clone()], 1).await;
        publish_grant(&bed.relay, &community, &owner.keys, &admin_b.public_key(), vec![rid], 1).await;

        let bundle = bundle_of(&community, BundleAudience::Link, Some(owner.keys.public_key()), None, None);
        let bundle_json = serde_json::to_string(&bundle).unwrap();
        bed.swap_to(&me);
        let joined = accept_parked_invite(&bed.relay, &bundle_json, None).await.unwrap();
        let _ = follow_control(&bed.relay, &joined).await;
        let joined = crate::db::community::load_community_v2(joined.id()).unwrap().unwrap();

        // Admin A re-founds keeping the owner + me but EXCLUDING peer admin B.
        publish_base_rotation(&bed.relay, &joined, &admin_a, &[owner.keys.public_key(), me.keys.public_key()], &[0xDD; 32], &joined.community_root).await;

        let follow = follow_rekeys(&bed.relay, &joined, &crate::db::current_session()).await.unwrap();
        assert!(follow.updated.is_none() && !follow.self_removed, "excluding an equal-rank peer admin is inadmissible");
    }

    #[tokio::test]
    async fn a_retried_refounding_reuses_the_same_root() {
        // B1 idempotency: minting for the same (scope, epoch) twice yields the SAME
        // root, so a retried Refounding re-delivers one root — never a double-mint fork.
        let (_tmp, _guard, _owner) = init_test_db();
        let relay = MemoryRelay::new();
        let community = create_community(&relay, "Retry", vec!["wss://r".into()], None).await.unwrap();
        let cid_hex = crate::simd::hex::bytes_to_hex_32(&community.id().0);
        let first = mint_or_reuse_rotation_key(&cid_hex, crate::community::SERVER_ROOT_SCOPE_HEX, 1).unwrap();
        let second = mint_or_reuse_rotation_key(&cid_hex, crate::community::SERVER_ROOT_SCOPE_HEX, 1).unwrap();
        assert_eq!(first, second, "a retry reuses the archived root, never double-mints");
    }

    #[tokio::test]
    async fn a_mid_rank_admin_cannot_demote_a_role_that_outranks_them() {
        // CORD-04 §2 rank inversion. Minting at a position you outrank is
        // necessary but NOT sufficient: an edition replaces the entity, so a
        // gate that only reads the NEW position lets an admin at position 5
        // rewrite the position-1 role to position 9. Every check passes (9 is
        // beneath them), and the role that outranked them — plus everyone
        // holding it — is now beneath them.
        let (bed, owner, attacker) = TestBed::new();
        bed.swap_to(&owner);
        let community = create_community(&bed.relay, "Ranks", bed.relays.clone(), None).await.unwrap();

        // A senior role at position 1, and a mid role at position 5 the attacker holds.
        let senior = "a1".repeat(32);
        let mid = "a5".repeat(32);
        publish_role(&bed.relay, &community, &owner.keys,
            &Role { role_id: senior.clone(), name: "Senior".into(), position: 1, permissions: Permissions(Permissions::BAN), scope: RoleScope::Server, color: 0 }, 1).await;
        publish_role(&bed.relay, &community, &owner.keys,
            &Role { role_id: mid.clone(), name: "Mid".into(), position: 5, permissions: Permissions(Permissions::MANAGE_ROLES), scope: RoleScope::Server, color: 0 }, 1).await;
        publish_grant(&bed.relay, &community, &owner.keys, &attacker.keys.public_key(), vec![mid.clone()], 1).await;

        // The attacker republishes the SENIOR role, dropping it beneath themselves.
        publish_role(&bed.relay, &community, &attacker.keys,
            &Role { role_id: senior.clone(), name: "Senior".into(), position: 9, permissions: Permissions(Permissions::BAN), scope: RoleScope::Server, color: 0 }, 2).await;

        let authority = fetch_authority(&bed.relay, &community).await;
        let folded_senior = authority.roles.role(&senior).expect("the senior role survives the fold");
        assert_eq!(
            folded_senior.position, 1,
            "a role may only be repositioned by someone who outranks where it STOOD, not just where it lands",
        );
    }

    #[tokio::test]
    async fn a_non_owner_admins_edition_cites_its_grant_and_the_owners_does_not() {
        // CORD-04 §5. Armada's reader REQUIRES this on every non-owner control
        // edition (`citationOk`: "a non-owner action MUST cite its grant"), so
        // an uncited Vector admin's ban/role/channel edit was silently dropped
        // by every Armada client — only the owner's actions crossed. The
        // citation must name the actor's OWN grant coordinate, at the version
        // and edition hash the verifier can match against a grant it holds.
        let (bed, owner, admin) = TestBed::new();
        bed.swap_to(&owner);
        let community = create_community(&bed.relay, "Cited", bed.relays.clone(), None).await.unwrap();
        let rid = "c1".repeat(32);
        publish_role(&bed.relay, &community, &owner.keys, &admin_role(&rid, Permissions::BAN | Permissions::MANAGE_METADATA), 1).await;
        publish_grant(&bed.relay, &community, &owner.keys, &admin.keys.public_key(), vec![rid], 1).await;

        // The owner's own edition carries NO citation: their rank is the id.
        let owner_meta = control::CommunityMetadata { name: "By Owner".into(), relays: community.relays.clone(), ..Default::default() };
        edit_community_metadata(&bed.relay, &community, &owner_meta).await.unwrap();
        let owner_ed = fetch_control(&bed.relay, &community).await.into_iter()
            .filter(|e| e.author == owner.keys.public_key() && e.vsk == vsk::COMMUNITY_METADATA)
            .max_by_key(|e| e.version).expect("the owner's metadata edition");
        assert!(owner_ed.authority.is_none(), "the owner cites nothing — rank comes from the community id");

        // The admin JOINS and folds — the citation names the grant head their own
        // client has actually synced, so the fold must have persisted it.
        let bundle = bundle_of(&community, BundleAudience::Link, Some(owner.keys.public_key()), None, None);
        let bundle_json = serde_json::to_string(&bundle).unwrap();
        bed.swap_to(&admin);
        let joined = accept_parked_invite(&bed.relay, &bundle_json, None).await.unwrap();
        let _ = follow_control(&bed.relay, &joined).await;
        let joined = crate::db::community::load_community_v2(joined.id()).unwrap().unwrap();
        set_banlist(&bed.relay, &joined, &["ee".repeat(32)]).await.unwrap();

        let ban_ed = fetch_control(&bed.relay, &joined).await.into_iter()
            .find(|e| e.author == admin.keys.public_key() && e.vsk == vsk::BANLIST)
            .expect("the admin's banlist edition");
        let cite = ban_ed.authority.as_ref().expect("a non-owner MUST cite its grant");
        assert_eq!(
            cite.entity_id,
            crate::community::v2::derive::grant_locator(community.id(), &admin.keys.public_key().to_bytes()),
            "the citation must name the ACTOR'S OWN grant coordinate",
        );
        assert!(cite.version >= 1, "pinned to a real grant version");
    }

    #[tokio::test]
    async fn a_folded_metadata_edition_cannot_push_the_relay_set_past_the_cap() {
        // `cap_relays` is the truncate-on-read invariant everywhere else, and the
        // fold is a boundary like any other: MANAGE_METADATA makes an editor
        // authorized, not trusted. An oversize list costs every member a fan-out
        // per publish and the slowest of N per fetch — and Armada caps at 5, so
        // an uncapped fold also splits the two clients' operative sets.
        let (_tmp, _guard, _owner) = init_test_db();
        let relay = MemoryRelay::new();
        let community = create_community(&relay, "Fanout", vec!["wss://a".into()], None).await.unwrap();

        let many: Vec<String> = (0..30).map(|i| format!("wss://r{i}")).collect();
        let meta = control::CommunityMetadata { name: "Fanout".into(), relays: many, ..Default::default() };
        edit_community_metadata(&relay, &community, &meta).await.unwrap();

        let updated = follow_control(&relay, &community).await.unwrap().updated
            .expect("the metadata edition is folded");
        assert_eq!(
            updated.relays.len(),
            crate::community::MAX_COMMUNITY_RELAYS,
            "a folded relay list must be truncated, never adopted whole",
        );

        // …and the fold must SETTLE: comparing an oversize edition against the
        // capped working set would never be equal, so every later fold would
        // report a change and re-save forever.
        let again = follow_control(&relay, &updated).await.unwrap().updated;
        assert!(again.is_none(), "re-folding the same oversize edition must be a no-op");
    }

    #[tokio::test]
    async fn adopting_a_rotation_writes_no_registry_where_i_never_minted() {
        // One Invite List spans every community, so "I hold links" must never be
        // read as "I hold links HERE". A member with links elsewhere adopting a
        // rotation would otherwise publish an empty Registry edition into this
        // community — a control-plane write and a version bump on a coordinate
        // they never owned, every rotation, forever.
        let (bed, owner, me) = TestBed::new();
        bed.swap_to(&owner);
        let host = create_community(&bed.relay, "Host", bed.relays.clone(), None).await.unwrap();
        let rid = "b2".repeat(32);
        publish_role(&bed.relay, &host, &owner.keys, &admin_role(&rid, Permissions::BAN), 1).await;
        publish_grant(&bed.relay, &host, &owner.keys, &me.keys.public_key(), vec![rid], 1).await;

        let bundle = bundle_of(&host, BundleAudience::Link, Some(owner.keys.public_key()), None, None);
        let bundle_json = serde_json::to_string(&bundle).unwrap();
        bed.swap_to(&me);
        let joined = accept_parked_invite(&bed.relay, &bundle_json, None).await.unwrap();
        let _ = follow_control(&bed.relay, &joined).await;
        let joined = crate::db::community::load_community_v2(joined.id()).unwrap().unwrap();

        // My only link lives in a DIFFERENT community — one I own, since minting
        // is offer-gated on CREATE_INVITE.
        let elsewhere = create_community(&bed.relay, "Elsewhere", bed.relays.clone(), None).await.unwrap();
        mint_public_link(&bed.relay, &elsewhere, "https://other", None, None).await.unwrap();

        let before = bed.relay.stored_count();
        let new_root = [0xE1; 32];
        publish_base_rotation(&bed.relay, &joined, &owner.keys, &[owner.keys.public_key(), me.keys.public_key()], &new_root, &joined.community_root).await;
        let rotation_events = bed.relay.stored_count() - before;

        let after_adopt = bed.relay.stored_count();
        follow_rekeys(&bed.relay, &joined, &crate::db::current_session()).await.unwrap();
        assert_eq!(
            bed.relay.stored_count(),
            after_adopt,
            "adopting a rotation must publish NOTHING when I minted no links here",
        );
        assert!(rotation_events > 0, "the rotation itself did publish (guards the counter)");
    }

    #[tokio::test]
    async fn an_expired_link_stops_keeping_the_community_public() {
        // CORD-05 §1/§5: expiry is the one way a link dies with no user action.
        // A joiner is refused by `InviteBundle::expired`, so leaving the link in
        // the Registry states a door that isn't there — the aggregate never
        // empties and the community reads Public forever, silently inverting
        // every gate that hangs off that reading.
        let (_tmp, _guard, _owner) = init_test_db();
        let relay = MemoryRelay::new();
        let community = create_community(&relay, "Lapsing", vec!["wss://r".into()], None).await.unwrap();

        // A link that lapsed a minute ago.
        let past = now_ms() - 60_000;
        mint_public_link(&relay, &community, "https://x", Some(past), None).await.unwrap();
        assert!(
            !community_is_public(&relay, &community).await,
            "an already-expired link must never read as a live door",
        );

        // …and one that hasn't, to prove the filter isn't just dropping everything.
        mint_public_link(&relay, &community, "https://y", Some(now_ms() + 600_000), None).await.unwrap();
        assert!(community_is_public(&relay, &community).await, "an unexpired link is still live");
    }

    #[tokio::test]
    async fn minting_a_link_makes_the_community_public_and_revoke_makes_it_private() {
        // CORD-05 §5: the Registry is the Public/Private source of truth. Minting a
        // link publishes it (Public); retiring the last link empties it (Private).
        let (_tmp, _guard, _owner) = init_test_db();
        let relay = MemoryRelay::new();
        let community = create_community(&relay, "Invitable", vec!["wss://r".into()], None).await.unwrap();
        assert!(!community_is_public(&relay, &community).await, "a fresh community is Private");

        let minted = mint_public_link(&relay, &community, "https://x", None, None).await.unwrap();
        assert!(community_is_public(&relay, &community).await, "a live link makes it Public");
        let list = fetch_invite_list(&relay, &community.relays).await.unwrap().expect("the 13303 list was published");
        assert_eq!(list.entries.len(), 1, "the minted link is recorded across devices");

        let token_hex = crate::simd::hex::bytes_to_hex_16(&minted.token);
        revoke_public_link(&relay, &community, &token_hex).await.unwrap();
        assert!(!community_is_public(&relay, &community).await, "retiring the last link makes it Private again");
        let after = fetch_invite_list(&relay, &community.relays).await.unwrap().unwrap();
        assert!(after.entries.is_empty() && after.tombstones.len() == 1, "the link is tombstoned in the invite list");
    }

    #[tokio::test]
    async fn the_registry_is_cached_locally_so_public_private_is_a_sync_read() {
        // Every caller reads the `invite_registry` COLUMN, never the async fold. v2
        // published the Registry to the plane but never mirrored it locally, so every
        // v2 community read Private no matter how many live links it had.
        let (_tmp, _guard, _owner) = init_test_db();
        let relay = MemoryRelay::new();
        let community = create_community(&relay, "Cached", vec!["wss://r".into()], None).await.unwrap();
        let cid_hex = crate::simd::hex::bytes_to_hex_32(&community.id().0);
        let cached = || crate::db::community::get_community_invite_registry(&cid_hex).unwrap();
        // The per-creator split is a SEPARATE table, and it drives the "first link flips
        // the community Public" confirm — an empty one re-asks on every later link.
        let per_creator = || crate::db::community::get_invite_link_sets(&cid_hex).unwrap();
        assert!(cached().is_empty(), "a fresh community caches an empty registry");
        assert!(per_creator().is_empty(), "…and no per-creator sets");

        let minted = mint_public_link(&relay, &community, "https://x", None, None).await.unwrap();
        assert!(!cached().is_empty(), "minting caches the registry, so the UI reads Public without folding");
        let sets = per_creator();
        assert_eq!(sets.len(), 1, "the minting creator gets a set");
        assert_eq!(sets[0].locators.len(), 1, "carrying exactly their one live link");

        // Both caches must SHRINK too — a union-only mirror would strand it Public.
        let token_hex = crate::simd::hex::bytes_to_hex_16(&minted.token);
        revoke_public_link(&relay, &community, &token_hex).await.unwrap();
        assert!(cached().is_empty(), "retiring the last link empties the cache back to Private");
        assert!(per_creator().is_empty(), "…and clears the per-creator sets");
    }

    #[tokio::test]
    async fn a_rogue_registry_fork_cannot_retire_the_owners_live_link() {
        // Registries are coordinate-bound to their creator, but `fold_head` picks an
        // equal-version winner AUTHOR-BLIND, by lowest inner id — and an author grinds
        // that freely by varying content. Folding before authorising would let any
        // member occupy the owner's registry head, fail the authority check, and drop
        // the whole registry: a live invite link silently retired, flipping the
        // community to Private and steering a moderator into the wrong ban remedy.
        let (_tmp, _guard, owner) = init_test_db();
        let relay = MemoryRelay::new();
        let community = create_community(&relay, "Forked", vec!["wss://r".into()], None).await.unwrap();
        mint_public_link(&relay, &community, "https://x", None, None).await.unwrap();
        assert!(community_is_public(&relay, &community).await, "a live link makes it Public");

        let cid = community.id();
        let control = control::ControlPlane::of(&community).write_group().unwrap();
        let eid = crate::community::v2::derive::invite_links_locator(cid, &owner.public_key().to_bytes());

        let query = Query {
            kinds: vec![stream::KIND_WRAP],
            authors: vec![control.pk_hex()],
            limit: Some(FOLLOW_PAGE),
            ..Default::default()
        };
        let wraps = relay.fetch(&query, &community.relays).await.unwrap();
        let target = wraps
            .iter()
            .filter_map(|w| control::open_control_edition(w, &control).ok().map(|(e, _)| e))
            .filter(|e| e.entity_id == eid)
            .max_by_key(|e| e.version)
            .expect("the owner published a registry");

        // Grind a same-version fork under the owner's coordinate that OUTRANKS the
        // real head on the tiebreak (~2 tries against a uniform id).
        let rogue = Keys::generate();
        let mut planted = false;
        for n in 0..4_000u64 {
            let content = format!("[{{\"token\":\"{n:032x}\",\"url\":\"https://evil\",\"expires_at\":0}}]");
            let rumor = control::build_edition_rumor(
                rogue.public_key(),
                vsk::INVITE_LINKS,
                &eid,
                target.version,
                target.prev_hash.as_ref(),
                &content,
                9_000,
                None,
            );
            let (w, _) = control::seal_control_edition(&rumor, &control, &rogue, Timestamp::from_secs(9_000)).unwrap();
            let (ed, _) = control::open_control_edition(&w, &control).unwrap();
            if ed.inner_id < target.inner_id {
                relay.publish(&w, &community.relays).await.unwrap();
                planted = true;
                break;
            }
        }
        assert!(planted, "the test needs a fork that wins the tiebreak");

        assert!(
            community_is_public(&relay, &community).await,
            "an unauthorised fork must not retire the owner's live link"
        );
    }

    #[tokio::test]
    async fn a_registry_from_a_non_create_invite_holder_does_not_make_it_public() {
        // The CREATE_INVITE gate: a rogue publishing a registry can't fake Public.
        let (_tmp, _guard, owner) = init_test_db();
        let relay = MemoryRelay::new();
        let community = create_community(&relay, "Gated", vec!["wss://r".into()], None).await.unwrap();
        let rogue = Keys::generate();
        // Rogue publishes a registry edition at THEIR coordinate with a fake signer.
        let eid = crate::community::v2::derive::invite_links_locator(community.id(), &rogue.public_key().to_bytes());
        let content = crate::community::v2::invite::build_registry_content(&[Keys::generate().public_key()]);
        let group = control::ControlPlane::of(&community).write_group().unwrap();
        let rumor = control::build_edition_rumor(rogue.public_key(), vsk::INVITE_LINKS, &eid, 1, None, &content, 1_000, None);
        let (wrap, _) = control::seal_control_edition(&rumor, &group, &rogue, Timestamp::from_secs(1_000)).unwrap();
        relay.publish(&wrap, &community.relays).await.unwrap();
        let _ = owner;
        assert!(!community_is_public(&relay, &community).await, "a non-CREATE_INVITE registry is ignored");
    }

    #[tokio::test]
    async fn full_lifecycle_e2e() {
        // The whole stack end to end across two accounts: create -> Public link ->
        // owner grants an admin -> member joins + reads history -> admin edits metadata
        // (authorized fold) -> owner bans the member (CORD-04 §6: banlist + strip +
        // Refounding) -> the banned member is severed AND stays banned across the new
        // epoch -> pre-ban history still reads -> owner dissolves -> sealed.
        let (bed, owner, member) = TestBed::new();

        bed.swap_to(&owner);
        let community = create_community(&bed.relay, "Lifecycle", bed.relays.clone(), None).await.unwrap();
        let general = community.channels[0].id;
        send_message(&bed.relay, &community, &general, "owner: welcome").await.unwrap();

        // Public link → the community reads Public.
        let _minted = mint_public_link(&bed.relay, &community, "https://x", None, None).await.unwrap();
        assert!(community_is_public(&bed.relay, &community).await, "a live link makes it Public");

        // Owner defines + grants an Admin role (MANAGE_METADATA among the bits).
        let rid = "aa".repeat(32);
        publish_role(&bed.relay, &community, &owner.keys, &admin_role(&rid, Permissions::ADMIN_ALL), 1).await;
        publish_grant(&bed.relay, &community, &owner.keys, &member.keys.public_key(), vec![rid], 1).await;

        // Member joins from the bundle + reads the owner's message.
        let bundle = bundle_of(&community, BundleAudience::Link, Some(owner.keys.public_key()), None, None);
        let bundle_json = serde_json::to_string(&bundle).unwrap();
        bed.swap_to(&member);
        let joined = accept_parked_invite(&bed.relay, &bundle_json, None).await.unwrap();
        assert_eq!(texts_in(&bed.relay, &joined, &general).await, vec!["owner: welcome"]);
        // The admin folds first — adopting the staff write key their Grant
        // delivered (CORD-04 §3) — then renames the community.
        let _ = follow_control(&bed.relay, &joined).await;
        let joined = crate::db::community::load_community_v2(joined.id()).unwrap().unwrap();
        assert!(joined.control_root.is_some(), "the Grant's control_wrap was adopted on fold");
        publish_community_meta(&bed.relay, &joined, &member.keys, "Lifecycle Renamed", 2).await;

        // Owner follows: the admin's rename folds (authorized).
        bed.swap_to(&owner);
        let updated = follow_control(&bed.relay, &community).await.unwrap().updated.expect("the admin edit folds");
        assert_eq!(updated.name, "Lifecycle Renamed", "an authorized admin's metadata edit is honored");

        // Ban the member (the three-removal composition, in order).
        set_banlist(&bed.relay, &updated, &[member.keys.public_key().to_hex()]).await.unwrap();
        grant_roles(&bed.relay, &updated, &member.keys.public_key(), vec![]).await.unwrap();
        let refounded = refound_community(&bed.relay, &updated, &[member.keys.public_key()]).await.unwrap();
        assert_eq!(refounded.root_epoch, Epoch(1), "the ban rolled the root");
        // The ban survives the Refounding (the banlist head compacted forward).
        let post = fold_authority(&refounded, &fetch_control(&bed.relay, &refounded).await, &load_floors(&refounded));
        assert!(post.banned.contains(&member.keys.public_key().to_hex()), "the ban survives the re-founding");
        // Pre-ban history still reads across the new epoch.
        assert!(
            all_texts_in(&bed.relay, &refounded, &general).await.contains(&"owner: welcome".to_string()),
            "pre-refounding history stays reachable by paging"
        );

        // The banned member's rekey-follow concludes they're severed. Guard captured AFTER
        // the swap (the harness swap bumps the generation like production).
        bed.swap_to(&member);
        let session = crate::db::current_session();
        let follow = follow_rekeys(&bed.relay, &joined, &session).await.unwrap();
        assert!(follow.self_removed, "the banned member is cryptographically cut");

        // Owner dissolves → sealed.
        bed.swap_to(&owner);
        dissolve_community(&bed.relay, &refounded).await.unwrap();
        assert!(crate::db::community::load_community_v2(community.id()).unwrap().unwrap().dissolved, "the community is sealed");
    }

    /// The deep two-account e2e the way a real deployment runs: owner (A) + member (B)
    /// over one shared relay, create → channels (public + private) → converse both ways →
    /// persist (get_messages-level) → react/edit/delete → moderate (ban/unban) → dissolve.
    /// Every account, community, channel, and action is LOGGED (run with --nocapture) so it
    /// doubles as a reference transcript and a re-runnable regression.
    #[tokio::test]
    async fn a_forged_edition_cannot_suppress_a_role_across_a_refounding() {
        // A member forges a higher-version role edition at the admin coordinate before a
        // refounding. The compaction must carry the AUTHORIZED floor head, not the
        // author-blind version tip — else the forgery is re-anchored, honest folders drop
        // it, and the admin role vanishes at the new epoch (silent suppression).
        let (bed, owner, member) = TestBed::new();
        let attacker = Keys::generate();
        bed.swap_to(&owner);
        let community = create_community(&bed.relay, "NoSuppress", bed.relays.clone(), None).await.unwrap();
        let rid = crate::simd::hex::bytes_to_hex_32(&[0xa1; 32]);
        publish_role(&bed.relay, &community, &owner.keys, &admin_role(&rid, Permissions::ADMIN_ALL), 1).await;
        publish_grant(&bed.relay, &community, &owner.keys, &member.keys.public_key(), vec![rid.clone()], 1).await;
        // Owner folds → the authorized role/grant heads are floored.
        follow_control(&bed.relay, &community).await.unwrap().updated;
        assert!(fetch_authority(&bed.relay, &community).await.roles.is_admin(&member.keys.public_key().to_hex()), "member is admin pre-attack");

        // The attacker (a non-owner) forges v2 of the admin role, chaining onto v1.
        publish_role(&bed.relay, &community, &attacker, &Role { role_id: rid.clone(), name: "pwn".into(), position: 1, permissions: Permissions(0), scope: RoleScope::Server, color: 0 }, 2).await;

        // Owner refounds (keeping everyone).
        let refounded = refound_community(&bed.relay, &community, &[]).await.unwrap();
        assert_eq!(refounded.root_epoch, Epoch(1), "root rolled");

        // Post-refound, the admin role SURVIVES (the authorized floor head was carried).
        let post = fold_authority(&refounded, &fetch_control(&bed.relay, &refounded).await, &load_floors(&refounded));
        assert!(post.roles.is_admin(&member.keys.public_key().to_hex()), "the admin role survives the refounding despite the forgery");
    }

    #[tokio::test]
    async fn memberlist_survives_a_refounding_via_the_snapshot() {
        // A silent survivor (didn't re-post at the new epoch) must stay in the memberlist
        // after a refounding — the owner's 3312 snapshot re-seeds them (CORD-02 §5).
        let (bed, owner, member) = TestBed::new();
        bed.swap_to(&owner);
        let community = create_community(&bed.relay, "Snapshot", bed.relays.clone(), None).await.unwrap();

        // Member joins (a Guestbook Join at epoch 0).
        let bundle = serde_json::to_string(&bundle_of(&community, BundleAudience::Link, Some(owner.keys.public_key()), None, None)).unwrap();
        bed.swap_to(&member);
        accept_parked_invite(&bed.relay, &bundle, None).await.unwrap();
        bed.swap_to(&owner);
        assert!(memberlist(&bed.relay, &community).await.unwrap().contains(&member.keys.public_key()), "member present pre-refound");

        // Owner refounds keeping everyone (removed = []); survivors are snapshotted to epoch 1.
        let refounded = refound_community(&bed.relay, &community, &[]).await.unwrap();
        assert_eq!(refounded.root_epoch, Epoch(1), "the root rolled");

        // The member is STILL a member at epoch 1 purely via the snapshot (never re-posted).
        let members = memberlist(&bed.relay, &refounded).await.unwrap();
        assert!(members.contains(&member.keys.public_key()), "a silent survivor stays a member after the refounding");
        assert!(members.contains(&owner.keys.public_key()), "owner is always a member");
    }

    #[tokio::test]
    async fn e2e_two_accounts_channels_converse_moderate() {
        use crate::community::v2::inbound::{apply_chat_to_state, persist_chat};
        use nostr_sdk::prelude::ToBech32;
        let (bed, a, b) = TestBed::new();
        let (a_npub, b_npub) = (a.keys.public_key().to_bech32().unwrap(), b.keys.public_key().to_bech32().unwrap());
        let (a_hex, b_hex) = (a.keys.public_key().to_hex(), b.keys.public_key().to_hex());
        println!("\n===== Concord v2 deep e2e =====");
        println!("[acct] A (owner)  = {a_npub}");
        println!("[acct] B (member) = {b_npub}");

        // ── A creates the community + a PRIVATE channel + two extra PUBLIC channels ──
        bed.swap_to(&a);
        let mut community = create_community(&bed.relay, "Deep E2E", bed.relays.clone(), None).await.unwrap();
        let general = community.channels[0].id;
        println!("[create] community {} · #general {}", crate::simd::hex::bytes_to_hex_32(&community.id().0), crate::simd::hex::bytes_to_hex_32(&general.0));

        // A PRIVATE channel via the REAL create path: an independent key minted at
        // channel-epoch 1, delivered over the rekey plane (A is the only member yet),
        // then announced (vsk 2) — later carried to B in the join bundle.
        let priv_id = create_private_channel(&bed.relay, &community, "mods").await.unwrap();
        community = crate::db::community::load_community_v2(community.id()).unwrap().unwrap();
        let priv_ch = community.channel(&priv_id).unwrap();
        assert!(priv_ch.private && priv_ch.key.is_some() && priv_ch.epoch == Epoch(1), "born-private: keyed at epoch 1");
        println!("[channel] +private #mods {} (native create: key over the rekey plane)", crate::simd::hex::bytes_to_hex_32(&priv_id.0));

        // Two more PUBLIC channels via the real create path.
        let announcements = create_public_channel(&bed.relay, &community, "announcements").await.unwrap();
        community = crate::db::community::load_community_v2(community.id()).unwrap().unwrap();
        let random = create_public_channel(&bed.relay, &community, "random").await.unwrap();
        community = crate::db::community::load_community_v2(community.id()).unwrap().unwrap();
        println!("[channel] +public #announcements {} · #random {}", crate::simd::hex::bytes_to_hex_32(&announcements.0), crate::simd::hex::bytes_to_hex_32(&random.0));
        assert_eq!(community.channels.len(), 4, "general + mods + announcements + random");

        // A talks in a few channels.
        let m1 = send_message(&bed.relay, &community, &general, "A: welcome to the deep e2e").await.unwrap();
        send_message(&bed.relay, &community, &announcements, "A: read the rules").await.unwrap();
        send_message(&bed.relay, &community, &priv_id, "A: mods-only channel").await.unwrap();
        println!("[msg] A posted in #general / #announcements / #mods");

        // ── A grants B admin, mints a public link, B joins from the bundle ──
        let admin_rid = crate::simd::hex::bytes_to_hex_32(&[0xa1; 32]);
        publish_role(&bed.relay, &community, &a.keys, &admin_role(&admin_rid, Permissions::ADMIN_ALL), 1).await;
        publish_grant(&bed.relay, &community, &a.keys, &b.keys.public_key(), vec![admin_rid], 1).await;
        let link = mint_public_link(&bed.relay, &community, "https://vectorapp.io", None, None).await.unwrap();
        assert!(community_is_public(&bed.relay, &community).await, "a live link makes it Public");
        println!("[invite] granted B @admin · minted link {}", link.url);

        // A private channel is readable only by granted role-holders (CORD-03), so
        // B is added to its access list before the bundle is minted.
        grant_channel_access(&bed.relay, &community, &priv_id, &b.keys.public_key()).await.unwrap();
        let bundle_json = serde_json::to_string(&bundle_of(&community, BundleAudience::Member(b.keys.public_key()), Some(a.keys.public_key()), None, None)).unwrap();
        bed.swap_to(&b);
        let mut b_view = accept_parked_invite(&bed.relay, &bundle_json, None).await.unwrap();
        println!("[join] B joined; sees {} channels", b_view.channels.len());
        assert_eq!(b_view.channels.len(), 4, "B receives all four channels (incl. the private one's key) in the bundle");
        assert!(b_view.channels.iter().any(|c| c.id.0 == priv_id.0 && c.private && c.key.is_some()), "B holds the private channel key");
        assert!(texts_in(&bed.relay, &b_view, &general).await.contains(&"A: welcome to the deep e2e".to_string()), "B reads A's #general history");
        assert!(texts_in(&bed.relay, &b_view, &priv_id).await.contains(&"A: mods-only channel".to_string()), "B reads the PRIVATE channel with the bundle key");
        // B folds the control plane (persisting the roster) — the live worker does
        // this right after any join; B's admin standing gates B's channel ops below.
        if let Some(fresh) = follow_control(&bed.relay, &b_view).await.unwrap().updated {
            b_view = fresh;
        }
        println!("[follow] B folded control (roster persisted: B is @admin)");

        // ── Conversation both ways + persistence (get_messages-level) ──
        send_message(&bed.relay, &b_view, &general, "B: thanks, glad to be here").await.unwrap();
        send_message(&bed.relay, &b_view, &priv_id, "B: mods checking in").await.unwrap();
        println!("[msg] B replied in #general + #mods");
        // Persist B's own #general view into the shared store (what sync/live ingest does)
        // and confirm it reads back via STATE — get_messages parity.
        let my_pk = b.keys.public_key();
        let gh = crate::simd::hex::bytes_to_hex_32(&general.0);
        for f in fetch_channel(&bed.relay, &b_view, &general, 100).await.unwrap() {
            let outcome = { let mut st = crate::state::STATE.lock().await; apply_chat_to_state(&mut st, &f.event, &gh, &my_pk) };
            if let Some(o) = outcome { persist_chat(&gh, &o).await; }
        }
        assert!(crate::db::events::event_exists(&m1).unwrap(), "A's message persisted into B's shared store (get_messages backfill)");
        println!("[persist] #general history persisted into the shared events store");

        // B (admin) reacts to + the author edits/deletes — the chat-op surface.
        send_reaction(&bed.relay, &b_view, &general, &m1, &a_hex, super::super::kind::MESSAGE, "🔥", None).await.unwrap();
        bed.swap_to(&a);
        let m_edit = send_message(&bed.relay, &community, &general, "A: this will be edited").await.unwrap();
        send_edit(&bed.relay, &community, &general, &m_edit, "A: edited!").await.unwrap();
        let m_del = send_message(&bed.relay, &community, &general, "A: this will be deleted").await.unwrap();
        send_delete(&bed.relay, &community, &general, &m_del, super::super::kind::MESSAGE).await.unwrap();
        println!("[ops] reaction + edit + delete round-tripped");

        // ── B creates a channel as admin, A folds it in ──
        bed.swap_to(&b);
        let bugs = create_public_channel(&bed.relay, &b_view, "bug-reports").await.unwrap();
        println!("[channel] B(admin) +public #bug-reports {}", crate::simd::hex::bytes_to_hex_32(&bugs.0));
        bed.swap_to(&a);
        if let Some(updated) = follow_control(&bed.relay, &community).await.unwrap().updated {
            community = updated;
        }
        assert!(community.channels.iter().any(|c| c.id.0 == bugs.0), "A folds in B's authorized new channel");
        println!("[follow] A folded in B's #bug-reports (now {} channels)", community.channels.len());

        // ── A creates a SECOND private channel while B is already a member. B is
        // NOT on its access list, so B learns the channel exists (control-follow,
        // keyless) and gets no key: CORD-03's private channel is readable only by
        // granted role-holders, never by every member. B keys up if and when A
        // grants them the channel's access role and vends the key ──
        let vault = create_private_channel(&bed.relay, &community, "vault").await.unwrap();
        community = crate::db::community::load_community_v2(community.id()).unwrap().unwrap();
        send_message(&bed.relay, &community, &vault, "A: vault is open").await.unwrap();
        println!("[channel] +private #vault {} (B is unentitled — no delivery)", crate::simd::hex::bytes_to_hex_32(&vault.0));
        bed.swap_to(&b);
        let session_b2 = crate::db::current_session();
        if let Some(fresh) = follow_control(&bed.relay, &b_view).await.unwrap().updated {
            b_view = fresh;
        }
        let ch = b_view.channel(&vault).expect("B recorded the announced private channel");
        assert!(ch.private && ch.key.is_none() && ch.epoch == Epoch(0), "B's record is keyless at cursor 0");
        let rf = follow_rekeys(&bed.relay, &b_view, &session_b2).await.unwrap();
        if let Some(fresh) = rf.updated {
            b_view = fresh;
        }
        let ch = b_view.channel(&vault).expect("still recorded");
        assert!(ch.key.is_none(), "an unentitled member is never delivered the key");
        assert!(
            texts_in(&bed.relay, &b_view, &vault).await.is_empty(),
            "and reads nothing from it"
        );
        assert!(
            send_message(&bed.relay, &b_view, &vault, "B: in the vault").await.is_err(),
            "an unentitled member cannot post into the channel either"
        );
        bed.swap_to(&a);
        community = crate::db::community::load_community_v2(community.id()).unwrap().unwrap();
        println!("[private] #vault stayed sealed to the unentitled B (no key, no read, no send)");

        // ── Members ──
        let members = memberlist(&bed.relay, &community).await.unwrap();
        let member_hexes: std::collections::BTreeSet<String> = members.iter().map(|m| m.to_hex()).collect();
        assert!(member_hexes.contains(&a_hex) && member_hexes.contains(&b_hex), "A + B both in the memberlist");
        println!("[members] {} members: A + B present", members.len());

        // ── Moderate: ban B (banlist + strip + refound), verify severance + survival ──
        set_banlist(&bed.relay, &community, &[b_hex.clone()]).await.unwrap();
        grant_roles(&bed.relay, &community, &b.keys.public_key(), vec![]).await.unwrap();
        let refounded = refound_community(&bed.relay, &community, &[b.keys.public_key()]).await.unwrap();
        assert_eq!(refounded.root_epoch, Epoch(1), "the ban rolled the root");
        let post = fold_authority(&refounded, &fetch_control(&bed.relay, &refounded).await, &load_floors(&refounded));
        assert!(post.banned.contains(&b_hex), "the ban survives the refounding");
        assert!(all_texts_in(&bed.relay, &refounded, &general).await.iter().any(|t| t == "A: welcome to the deep e2e"), "pre-ban history pages back across the new epoch");
        assert!(
            all_texts_in(&bed.relay, &refounded, &priv_id).await.iter().any(|t| t == "A: mods-only channel"),
            "PRIVATE history pages back across the channel's own rotation (per-channel multi-epoch archive)"
        );
        println!("[ban] B banned; root rolled to epoch 1; ban survives; pre-ban history intact (public + private)");
        // B concludes it's severed.
        bed.swap_to(&b);
        let session_b3 = crate::db::current_session();
        assert!(follow_rekeys(&bed.relay, &b_view, &session_b3).await.unwrap().self_removed, "B is cryptographically cut by the ban-refound");
        println!("[ban] B's rekey-follow: self_removed = true (severed)");

        // ── Unban: A lifts the ban ──
        bed.swap_to(&a);
        set_banlist(&bed.relay, &refounded, &[]).await.unwrap();
        let after_unban = fold_authority(&refounded, &fetch_control(&bed.relay, &refounded).await, &load_floors(&refounded));
        assert!(!after_unban.banned.contains(&b_hex), "the unban clears B from the banlist");
        println!("[unban] B removed from the banlist (re-invitable)");

        // ── Dissolve ──
        dissolve_community(&bed.relay, &refounded).await.unwrap();
        assert!(crate::db::community::load_community_v2(community.id()).unwrap().unwrap().dissolved, "the community is sealed");
        println!("[dissolve] community sealed (read-only)\n===== e2e PASS =====\n");
    }

    /// The same scenario on a REAL relay with TWO throwaway accounts, off by default. It
    /// LOGS both nsecs (+ every id) so you can inspect the run and RE-RUN against the same
    /// accounts by exporting `VECTOR_E2E_NSEC_A` / `_B`. Set `VECTOR_E2E_LOG=<path>` to also
    /// append the transcript to a file, `VECTOR_E2E_RELAY=<url>` to pick the relay.
    ///   cargo test -p vector-core -- --ignored --nocapture live_e2e_two_accounts
    #[tokio::test]
    #[ignore]
    async fn live_e2e_two_accounts() {
        use crate::community::transport::LiveTransport;
        use nostr_sdk::prelude::ToBech32;

        let relay = std::env::var("VECTOR_E2E_RELAY").unwrap_or_else(|_| "wss://jskitty.com/nostr".to_string());
        let relays = vec![relay.clone()];
        let _g = crate::db::DB_TEST_GUARD.lock().unwrap_or_else(|e| e.into_inner());
        crate::db::close_database();
        crate::db::clear_id_caches();
        let tmp = tempfile::tempdir().unwrap();
        crate::db::set_app_data_dir(crate::db::shared_test_data_dir().to_path_buf());

        // Throwaway (or bring-your-own via env for a re-run against the same accounts).
        let a = std::env::var("VECTOR_E2E_NSEC_A").ok().and_then(|n| Keys::parse(&n).ok()).unwrap_or_else(Keys::generate);
        let b = std::env::var("VECTOR_E2E_NSEC_B").ok().and_then(|n| Keys::parse(&n).ok()).unwrap_or_else(Keys::generate);

        let log = |line: String| {
            println!("{line}");
            if let Ok(p) = std::env::var("VECTOR_E2E_LOG") {
                use std::io::Write;
                if let Ok(mut f) = std::fs::OpenOptions::new().create(true).append(true).open(&p) {
                    let _ = writeln!(f, "{line}");
                }
            }
        };
        log(format!("===== LIVE Concord v2 e2e on {relay} ====="));
        log(format!("VECTOR_E2E_NSEC_A={}  ({})", a.secret_key().to_bech32().unwrap(), a.public_key().to_bech32().unwrap()));
        log(format!("VECTOR_E2E_NSEC_B={}  ({})", b.secret_key().to_bech32().unwrap(), b.public_key().to_bech32().unwrap()));

        for k in [&a, &b] {
            let npub = k.public_key().to_bech32().unwrap();
            std::fs::create_dir_all(tmp.path().join(&npub)).unwrap();
            crate::db::set_current_account(npub.clone()).unwrap();
            crate::db::init_database(&npub).unwrap();
        }
        // One relay connection: a v2 wrap is pre-signed (ephemeral p-key) and its seal is
        // signed by MY_SECRET_KEY, so publishing needs no per-account client signer.
        let client = crate::nostr_client_builder().build();
        client.add_managed_relay(relay.as_str()).await.ok();
        client.connect().await;
        crate::state::set_nostr_client(client);
        let transport = LiveTransport::with_timeout(std::time::Duration::from_secs(15));
        let become_acct = |k: &Keys| {
            let npub = k.public_key().to_bech32().unwrap();
            crate::db::set_current_account(npub.clone()).unwrap();
            crate::db::init_database(&npub).unwrap();
            crate::db::clear_id_caches();
            crate::state::MY_SECRET_KEY.store_from_keys(k, &[]);
            crate::state::set_my_public_key(k.public_key());
        };
        let settle = || tokio::time::sleep(std::time::Duration::from_secs(2));

        // A: create + a channel + grant B admin + mint link.
        become_acct(&a);
        let mut community = create_community(&transport, "Live E2E", relays.clone(), None).await.expect("create");
        let general = community.channels[0].id;
        log(format!("[create] community {} · #general {}", crate::simd::hex::bytes_to_hex_32(&community.id().0), crate::simd::hex::bytes_to_hex_32(&general.0)));
        send_message(&transport, &community, &general, "A: live hello").await.expect("send");
        let ann = create_public_channel(&transport, &community, "announcements").await.expect("channel");
        community = crate::db::community::load_community_v2(community.id()).unwrap().unwrap();
        log(format!("[channel] +public #announcements {}", crate::simd::hex::bytes_to_hex_32(&ann.0)));
        grant_admin(&transport, &community, &b.public_key()).await.expect("grant admin");
        let link = mint_public_link(&transport, &community, "https://vectorapp.io", None, None).await.expect("mint");
        log(format!("[invite] B granted @admin · link {}", link.url));
        let bundle_json = serde_json::to_string(&bundle_of(&community, BundleAudience::Link, Some(a.public_key()), None, None)).unwrap();
        settle().await;

        // B: join + read A's history + reply.
        become_acct(&b);
        let b_view = accept_parked_invite(&transport, &bundle_json, None).await.expect("join");
        log(format!("[join] B joined; {} channels", b_view.channels.len()));
        settle().await;
        let page = fetch_channel(&transport, &b_view, &general, 50).await.expect("fetch");
        let seen: Vec<String> = page.iter().map(|f| f.event.opened().rumor.content.clone()).collect();
        log(format!("[read] B sees #general: {seen:?}"));
        assert!(seen.iter().any(|t| t == "A: live hello"), "B reads A's message over the real relay");
        send_message(&transport, &b_view, &general, "B: live reply").await.expect("reply");

        // B posts a NIP-22 kind-1111 THREADED REPLY to A's message (the shape Armada
        // sends) directly onto the chat plane — proving the cross-client thread
        // RECEIVE path works live, not just in the offline fixture.
        let hello = page.iter().find(|f| f.event.opened().rumor.content == "A: live hello").expect("A's message");
        let hello_id = hello.event.opened().rumor_id.to_hex();
        let bkeys = crate::state::MY_SECRET_KEY.to_keys().unwrap();
        let cgroup = channel_group_key(&b_view.community_root, &general, b_view.root_epoch);
        let reply_rumor = chat::build_comment_rumor(bkeys.public_key(), &general, b_view.root_epoch, "B: threaded reply to hello", &hello_id, super::super::kind::MESSAGE, &a.public_key().to_hex(), None, &[], now_ms());
        let (reply_wrap, _) = chat::seal_chat_rumor(&reply_rumor, &cgroup, &bkeys, Timestamp::from_secs(now_ms() / 1000), false).expect("seal 1111");
        transport.publish(&reply_wrap, &b_view.relays).await.expect("publish 1111");
        log("[thread] B published a kind-1111 threaded reply to A's message".to_string());
        settle().await;

        // A reads the thread reply back, rendered inline with A's message as parent.
        become_acct(&a);
        community = crate::db::community::load_community_v2(community.id()).unwrap().unwrap();
        let a_page = fetch_channel(&transport, &community, &general, 50).await.expect("A fetch");
        let thread = a_page.iter().find(|f| f.event.opened().rumor.content == "B: threaded reply to hello").expect("A sees the 1111");
        if let chat::ChatEvent::Message { reply_to, opened, .. } = &thread.event {
            assert_eq!(opened.rumor.kind.as_u16(), super::super::kind::COMMENT, "wire kind preserved as 1111");
            assert_eq!(reply_to.as_ref().map(|r| crate::simd::hex::bytes_to_hex_32(&r.id)), Some(hello_id.clone()), "the 1111 renders inline with A's message as parent");
        } else {
            panic!("the 1111 parsed as a Message");
        }
        log("[thread] A read B's threaded reply, parent resolved — cross-client 1111 interop OK".to_string());
        become_acct(&b);
        settle().await;

        // A: create a PRIVATE channel while B is already a member — B is a recipient
        // of the creation delivery, so B keys up from the rekey plane over the real
        // relay (no bundle involved), then the two converse on it.
        become_acct(&a);
        community = crate::db::community::load_community_v2(community.id()).unwrap().unwrap();
        let vault = create_private_channel(&transport, &community, "vault").await.expect("private channel");
        community = crate::db::community::load_community_v2(community.id()).unwrap().unwrap();
        send_message(&transport, &community, &vault, "A: vault live").await.expect("vault send");
        log(format!("[channel] +private #vault {} (key delivered over the rekey plane)", crate::simd::hex::bytes_to_hex_32(&vault.0)));
        settle().await;

        become_acct(&b);
        let session_b = crate::db::current_session();
        let mut b_view = crate::db::community::load_community_v2(b_view.id()).unwrap().unwrap();
        if let Some(fresh) = follow_control(&transport, &b_view).await.expect("B control follow").updated {
            b_view = fresh;
        }
        if let Some(fresh) = follow_rekeys(&transport, &b_view, &session_b).await.expect("B rekey follow").updated {
            b_view = fresh;
        }
        let vch = b_view.channel(&vault).expect("B folded the vault");
        assert!(vch.key.is_some() && vch.epoch == Epoch(1), "B adopted the vault key from the live rekey plane");
        let vseen = texts_in(&transport, &b_view, &vault).await;
        log(format!("[read] B sees #vault: {vseen:?}"));
        assert!(vseen.iter().any(|t| t == "A: vault live"), "B reads the private channel with the ADOPTED key");
        send_message(&transport, &b_view, &vault, "B: in the live vault").await.expect("vault reply");
        settle().await;

        become_acct(&a);
        community = crate::db::community::load_community_v2(community.id()).unwrap().unwrap();
        assert!(
            texts_in(&transport, &community, &vault).await.iter().any(|t| t == "B: in the live vault"),
            "A reads B's private reply"
        );
        log("[private] two-way #vault conversation over the live relay".to_string());

        // A: ban B (three-removal) + dissolve.
        set_banlist(&transport, &community, &[b.public_key().to_hex()]).await.expect("banlist");
        grant_roles(&transport, &community, &b.public_key(), vec![]).await.expect("strip");
        let refounded = refound_community(&transport, &community, &[b.public_key()]).await.expect("refound");
        log(format!("[ban] B banned; root → epoch {}", refounded.root_epoch.0));
        settle().await;
        dissolve_community(&transport, &refounded).await.expect("dissolve");
        log("[dissolve] community sealed".to_string());
        log("===== LIVE e2e PASS =====".to_string());
    }

    #[tokio::test]
    async fn an_offline_member_learns_of_a_dissolution_on_catch_up() {
        // The tombstone rides its own public plane, watched live — an OFFLINE
        // member's catch-up must fetch it too, or they follow (and post into) a
        // grave forever.
        let (bed, owner, member) = TestBed::new();
        bed.swap_to(&owner);
        let community = create_community(&bed.relay, "Doomed", bed.relays.clone(), None).await.unwrap();
        let general = community.channels[0].id;
        send_direct_invite(&bed.relay, &community, &member.keys.public_key(), None, None).await.unwrap();

        bed.swap_to(&member);
        let invite_wrap = fetch_direct_invite(&bed.relay, &bed.relays, &member.keys.public_key()).await;
        let joined = accept_direct_invite(&bed.relay, &invite_wrap).await.unwrap();

        // The owner dissolves while the member sleeps.
        bed.swap_to(&owner);
        dissolve_community(&bed.relay, &community).await.unwrap();

        // The member's catch-up learns of the death, seals, and refuses to post.
        bed.swap_to(&member);
        let session = crate::db::current_session();
        let follow = follow_rekeys(&bed.relay, &joined, &session).await.unwrap();
        assert!(follow.dissolved, "the catch-up surfaces the tombstone");
        assert!(!follow.self_removed && follow.updated.is_none());
        let cid_hex = crate::simd::hex::bytes_to_hex_32(&joined.id().0);
        assert!(crate::db::community::get_community_dissolved(&cid_hex).unwrap(), "sealed read-only locally");
        let err = send_message(&bed.relay, &joined, &general, "into the void").await.unwrap_err();
        assert!(err.contains("dissolved"), "sends refuse a grave: {err}");
        // Subsequent follows take the local fast path — still dissolved, no churn.
        let again = follow_rekeys(&bed.relay, &joined, &session).await.unwrap();
        assert!(again.dissolved && again.updated.is_none());
    }

    #[tokio::test]
    async fn a_wide_community_survives_refoundings_and_an_offline_member_converges() {
        // Scale stress: MANY private channels, each rotated on every Refounding.
        // A member offline across two refoundings must converge on all of them
        // (the per-channel rotation fan in refound + the follow's channel×root×step
        // loops stay bounded) with every channel's history readable.
        const PRIV_CHANNELS: usize = 6;
        let (bed, owner, member) = TestBed::new();
        bed.swap_to(&owner);
        let mut community = create_community(&bed.relay, "Wide", bed.relays.clone(), None).await.unwrap();
        let mut priv_ids = Vec::new();
        for i in 0..PRIV_CHANNELS {
            let id = create_private_channel(&bed.relay, &community, &format!("priv{i}")).await.unwrap();
            community = crate::db::community::load_community_v2(community.id()).unwrap().unwrap();
            send_message(&bed.relay, &community, &id, &format!("priv{i} epoch0")).await.unwrap();
            priv_ids.push(id);
        }
        // Private channels are readable only by granted role-holders (CORD-03).
        for id in &priv_ids {
            grant_channel_access(&bed.relay, &community, id, &member.keys.public_key()).await.unwrap();
        }
        let bundle_json = serde_json::to_string(&bundle_of(&community, BundleAudience::Member(member.keys.public_key()), Some(owner.keys.public_key()), None, None)).unwrap();

        // Member joins at epoch 0 with all channel keys, then goes offline.
        bed.swap_to(&member);
        let member_view = accept_parked_invite(&bed.relay, &bundle_json, None).await.unwrap();
        assert_eq!(member_view.channels.iter().filter(|c| c.private && c.key.is_some()).count(), PRIV_CHANNELS, "joined with all private keys");

        // Two refoundings (each rotates the base + every private channel).
        bed.swap_to(&owner);
        for epoch in 1..=2u64 {
            community = refound_community(&bed.relay, &community, &[]).await.unwrap();
            assert_eq!(community.root_epoch, Epoch(epoch));
            for id in &priv_ids {
                send_message(&bed.relay, &community, id, &format!("{} epoch{epoch}", crate::simd::hex::bytes_to_hex_32(&id.0))).await.unwrap();
            }
        }

        // Member returns: bounded follow to quiescence.
        bed.swap_to(&member);
        let session = crate::db::current_session();
        let mut passes = 0;
        loop {
            passes += 1;
            assert!(passes <= 8, "a wide catch-up must converge, not churn (pass {passes})");
            let cur = crate::db::community::load_community_v2(member_view.id()).unwrap().unwrap();
            let rk = follow_rekeys(&bed.relay, &cur, &session).await.unwrap();
            assert!(!rk.self_removed);
            let cur = crate::db::community::load_community_v2(member_view.id()).unwrap().unwrap();
            let ctl = follow_control(&bed.relay, &cur).await.unwrap().updated;
            if rk.updated.is_none() && ctl.is_none() {
                break;
            }
        }
        let caught_up = crate::db::community::load_community_v2(member_view.id()).unwrap().unwrap();
        assert_eq!(caught_up.root_epoch, Epoch(2), "walked both refoundings");
        // Every private channel converged to the owner's current key + reads all epochs.
        for id in &priv_ids {
            let mine = caught_up.channel(id).expect("channel survived");
            let theirs = community.channel(id).unwrap();
            assert_eq!(mine.key, theirs.key, "channel {} converged on the owner key", crate::simd::hex::bytes_to_hex_32(&id.0));
            assert_eq!(mine.epoch, theirs.epoch, "…at the same epoch");
            let id_hex = crate::simd::hex::bytes_to_hex_32(&id.0);
            // Opening reads the live planes; the rotated-past ones are the
            // back-paging cursor's job. Both halves asserted — the point is that
            // every epoch stays REACHABLE, not that opening drags it all in.
            let open = texts_in(&bed.relay, &caught_up, id).await;
            assert!(open.iter().any(|t| t.contains("epoch2")), "channel {id_hex} opens onto its live epoch");
            let paged = all_texts_in(&bed.relay, &caught_up, id).await;
            assert!(paged.iter().any(|t| t.contains("epoch0")), "channel {id_hex} pages back to epoch-0 history");
            for epoch in 1..=2u64 {
                assert!(paged.iter().any(|t| t.contains(&format!("epoch{epoch}"))), "channel {id_hex} pages back to epoch-{epoch} history");
            }
        }
    }

    #[tokio::test]
    async fn a_backlog_deeper_than_max_steps_still_converges() {
        // MAX_STEPS bounds ONE walk, not the catch-up. A member who slept through more
        // rotations than the bound must still land on the head — silently stopping at
        // the bound leaves them on a dead epoch reading nothing, which is
        // indistinguishable from a quiet community.
        let (bed, owner, member) = TestBed::new();
        bed.swap_to(&owner);
        let mut community = create_community(&bed.relay, "DeepSleeper", bed.relays.clone(), None).await.unwrap();
        let bundle_json = serde_json::to_string(&bundle_of(&community, BundleAudience::Member(member.keys.public_key()), Some(owner.keys.public_key()), None, None)).unwrap();

        bed.swap_to(&member);
        let joined = accept_parked_invite(&bed.relay, &bundle_json, None).await.unwrap();
        assert_eq!(joined.root_epoch, Epoch(0));

        // Past the bound, deliberately.
        bed.swap_to(&owner);
        let depth = MAX_WALK_STEPS + 3;
        for _ in 0..depth {
            community = refound_community(&bed.relay, &community, &[]).await.unwrap();
        }
        assert_eq!(community.root_epoch, Epoch(depth as u64));

        // The member follows repeatedly, exactly as a client does on each sync. Every
        // pass must make forward progress and none may lose ground.
        bed.swap_to(&member);
        let mut last = 0u64;
        for pass in 1..=8 {
            // Reload from the DB each pass, exactly as a client does: this is what
            // proves every hop was CHECKPOINTED, not merely held in the walk's memory.
            let view = crate::db::community::load_community_v2(community.id()).unwrap().unwrap();
            let session = crate::db::current_session();
            let _ = follow_rekeys(&bed.relay, &view, &session).await.unwrap();
            let view = crate::db::community::load_community_v2(community.id()).unwrap().unwrap();
            assert!(
                view.root_epoch.0 >= last,
                "pass {pass} lost ground: {} -> {}",
                last, view.root_epoch.0
            );
            last = view.root_epoch.0;
            if last == depth as u64 {
                break;
            }
        }
        let view = crate::db::community::load_community_v2(community.id()).unwrap().unwrap();
        assert_eq!(
            view.root_epoch, Epoch(depth as u64),
            "a backlog deeper than one walk's step bound must still converge across passes",
        );
    }

    #[tokio::test]
    async fn an_offline_member_catches_up_across_three_refoundings() {
        // The deep offline-online scenario: a member sleeps through THREE
        // Refoundings, per-refound private-channel rotations, a mid-life private
        // channel CREATED while they slept, a public channel, a rename, and a
        // ban — then returns and converges by follow alone (no rejoin).
        use nostr_sdk::prelude::ToBech32;
        let (bed, owner, member) = TestBed::new();
        bed.swap_to(&owner);
        let mut community = create_community(&bed.relay, "Sleeper", bed.relays.clone(), None).await.unwrap();
        let general = community.channels[0].id;
        let mods = create_private_channel(&bed.relay, &community, "mods").await.unwrap();
        community = crate::db::community::load_community_v2(community.id()).unwrap().unwrap();
        send_message(&bed.relay, &community, &general, "epoch0: hello").await.unwrap();
        send_message(&bed.relay, &community, &mods, "epoch0: mods secret").await.unwrap();
        // Private channels are readable only by granted role-holders (CORD-03).
        grant_channel_access(&bed.relay, &community, &mods, &member.keys.public_key()).await.unwrap();
        let bundle_json = serde_json::to_string(&bundle_of(&community, BundleAudience::Member(member.keys.public_key()), Some(owner.keys.public_key()), None, None)).unwrap();

        // Member joins at epoch 0, then goes OFFLINE.
        bed.swap_to(&member);
        let member_view = accept_parked_invite(&bed.relay, &bundle_json, None).await.unwrap();
        assert_eq!(member_view.root_epoch, Epoch(0));

        // While they sleep, the owner reshapes everything across three epochs.
        bed.swap_to(&owner);
        let stranger = Keys::generate();
        for epoch in 1..=3u64 {
            community = refound_community(&bed.relay, &community, &[]).await.unwrap();
            assert_eq!(community.root_epoch, Epoch(epoch));
            send_message(&bed.relay, &community, &general, &format!("epoch{epoch}: general news")).await.unwrap();
            send_message(&bed.relay, &community, &mods, &format!("epoch{epoch}: mods word")).await.unwrap();
        }
        let news = create_public_channel(&bed.relay, &community, "news").await.unwrap();
        community = crate::db::community::load_community_v2(community.id()).unwrap().unwrap();
        let vault = create_private_channel(&bed.relay, &community, "vault").await.unwrap();
        community = crate::db::community::load_community_v2(community.id()).unwrap().unwrap();
        // The sleeper is on this channel's access list, so the refoundings that
        // follow deliver its key to them (CORD-03).
        grant_channel_access(&bed.relay, &community, &vault, &member.keys.public_key()).await.unwrap();
        community = crate::db::community::load_community_v2(community.id()).unwrap().unwrap();
        send_message(&bed.relay, &community, &vault, "epoch3: vault opened").await.unwrap();
        set_banlist(&bed.relay, &community, &[stranger.public_key().to_hex()]).await.unwrap();
        let meta = control::CommunityMetadata { name: "Sleeper Reborn".into(), relays: community.relays.clone(), ..Default::default() };
        edit_community_metadata(&bed.relay, &community, &meta).await.unwrap();

        // The member RETURNS: rekey+control follow to quiescence (the worker's
        // loop, driven explicitly). Bounded — convergence must be fast.
        bed.swap_to(&member);
        let session = crate::db::current_session();
        let mut passes = 0;
        loop {
            passes += 1;
            assert!(passes <= 6, "catch-up must converge, not churn");
            let cur = crate::db::community::load_community_v2(member_view.id()).unwrap().unwrap();
            let rekeyed = follow_rekeys(&bed.relay, &cur, &session).await.unwrap();
            assert!(!rekeyed.self_removed, "the member was never removed");
            let cur = crate::db::community::load_community_v2(member_view.id()).unwrap().unwrap();
            let controlled = follow_control(&bed.relay, &cur).await.unwrap().updated;
            if rekeyed.updated.is_none() && controlled.is_none() {
                break;
            }
        }
        let caught_up = crate::db::community::load_community_v2(member_view.id()).unwrap().unwrap();

        // Base + name converged.
        assert_eq!(caught_up.root_epoch, Epoch(3), "walked all three refoundings");
        assert_eq!(caught_up.community_root, community.community_root, "landed on the owner's root");
        assert_eq!(caught_up.name, "Sleeper Reborn");
        // Channels: renamed set incl. the mid-sleep public + private ones.
        assert!(caught_up.channels.iter().any(|c| c.id.0 == news.0), "folded the new public channel");
        let m = caught_up.channel(&mods).expect("mods survived");
        let owner_mods = community.channel(&mods).unwrap();
        assert_eq!(m.epoch, owner_mods.epoch, "mods walked every per-refound rotation");
        assert_eq!(m.key, owner_mods.key, "…to the owner's exact key");
        let v = caught_up.channel(&vault).expect("vault folded in");
        // The sleeper is on vault's access list, but it was created AFTER the last
        // refounding — no rotation followed the grant, so no blob was ever
        // addressed to them. They hold the channel keyless until the grant's own
        // key vend lands (CORD-05 §6), which is what a rekey-only walk cannot do.
        assert!(v.private && v.key.is_none(), "vault folds in keyless: entitled, but never delivered");
        // Banlist survived the compactions.
        let cid_hex = crate::simd::hex::bytes_to_hex_32(&caught_up.id().0);
        let banned = crate::db::community::get_community_banlist(&cid_hex).unwrap();
        assert!(banned.contains(&stranger.public_key().to_hex()), "the ban folded through");
        // Opening reads the live planes only; paging back reaches EVERY epoch
        // (public via the base-root archive, private via the per-channel archive
        // built during the walk). A sleeper's deep history stays reachable — it
        // just arrives when they scroll for it rather than on open.
        let gen_open = texts_in(&bed.relay, &caught_up, &general).await;
        assert!(gen_open.contains(&"epoch3: general news".to_string()), "general opens onto its live epoch: {gen_open:?}");
        let gen_texts = all_texts_in(&bed.relay, &caught_up, &general).await;
        for epoch in 0..=3u64 {
            let needle = if epoch == 0 { "epoch0: hello".to_string() } else { format!("epoch{epoch}: general news") };
            assert!(gen_texts.contains(&needle), "general pages back to epoch {epoch}: {gen_texts:?}");
        }
        let mods_open = texts_in(&bed.relay, &caught_up, &mods).await;
        assert!(mods_open.contains(&"epoch3: mods word".to_string()), "mods opens onto its live epoch: {mods_open:?}");
        let mods_texts = all_texts_in(&bed.relay, &caught_up, &mods).await;
        for epoch in 0..=3u64 {
            let needle = if epoch == 0 { "epoch0: mods secret".to_string() } else { format!("epoch{epoch}: mods word") };
            assert!(mods_texts.contains(&needle), "private pages back to epoch {epoch}: {mods_texts:?}");
        }
        // Keyless (above) means unreadable — a rekey walk cannot substitute for the
        // key vend that a grant carries.
        assert!(texts_in(&bed.relay, &caught_up, &vault).await.is_empty());
        // And the member can still speak.
        send_message(&bed.relay, &caught_up, &general, "member: good morning").await.unwrap();
        bed.swap_to(&owner);
        assert!(
            texts_in(&bed.relay, &community, &general).await.contains(&"member: good morning".to_string()),
            "the caught-up member converses at the new epoch ({})",
            member.keys.public_key().to_bech32().unwrap()
        );
    }

    /// Seal `n` messages onto a community's #general, one per second starting at
    /// `base_secs` (distinct wrap seconds so relay-side `until` paging engages).
    async fn flood_general(relay: &MemoryRelay, community: &CommunityV2, author: &Keys, n: usize, base_secs: u64) {
        let general = community.channels[0].id;
        let group = channel_group_key(&community.community_root, &general, community.root_epoch);
        for i in 0..n {
            let at = base_secs + i as u64;
            let rumor = chat::build_message_rumor(author.public_key(), &general, community.root_epoch, &format!("msg {i}"), None, &[], vec![], at * 1000);
            let (wrap, _) = chat::seal_chat_rumor(&rumor, &group, author, Timestamp::from_secs(at), false).unwrap();
            relay.publish(&wrap, &community.relays).await.unwrap();
        }
    }

    #[tokio::test]
    async fn the_history_walk_pages_past_a_multi_page_burst() {
        // A bot offline through 120 messages must catch ALL of them, not the
        // newest page — the v1 sync-gap class, closed by until-paging.
        let (_tmp, _guard, owner) = init_test_db();
        let relay = MemoryRelay::new();
        let community = create_community(&relay, "Burst", vec!["wss://r".into()], None).await.unwrap();
        let general = community.channels[0].id;
        flood_general(&relay, &community, &owner, 120, 10_000).await;

        let all = fetch_channel_history(&relay, &community, &general, 50, 8, None, None, crate::community::transport::Evidence::Quorum, |_| true).await.unwrap();
        assert_eq!(all.len(), 120, "the walk pages the whole burst");
        // Oldest→newest, no duplicates.
        let contents: Vec<String> = all.iter().map(|f| f.event.opened().rumor.content.clone()).collect();
        assert_eq!(contents.first().map(String::as_str), Some("msg 0"));
        assert_eq!(contents.last().map(String::as_str), Some("msg 119"));
        let unique: std::collections::HashSet<&String> = contents.iter().collect();
        assert_eq!(unique.len(), 120, "wrap-id + rumor-id dedup holds across page boundaries");

        // The single-page fetch stays a single page.
        let one = fetch_channel(&relay, &community, &general, 50).await.unwrap();
        assert_eq!(one.len(), 50, "fetch_channel is one newest page");
        assert_eq!(one.last().map(|f| f.event.opened().rumor.content.clone()).as_deref(), Some("msg 119"));
    }

    #[tokio::test]
    async fn a_start_until_cursor_pages_history_from_that_point_backwards() {
        // The back-paging cursor: a walk that starts at an explicit `until`
        // returns only what lies at-or-before it, oldest→newest — the relay-side
        // half of the SDK's walk-until-dry loop.
        let (_tmp, _guard, owner) = init_test_db();
        let relay = MemoryRelay::new();
        let community = create_community(&relay, "Paged", vec!["wss://r".into()], None).await.unwrap();
        let general = community.channels[0].id;
        flood_general(&relay, &community, &owner, 120, 10_000).await;

        let older = fetch_channel_history(
            &relay, &community, &general, 50, 8, None, Some(10_059),
            crate::community::transport::Evidence::Quorum, |_| true,
        )
        .await
        .unwrap();
        let contents: Vec<String> = older.iter().map(|f| f.event.opened().rumor.content.clone()).collect();
        assert_eq!(contents.len(), 60, "everything at-or-before the cursor, nothing after");
        assert_eq!(contents.first().map(String::as_str), Some("msg 0"));
        assert_eq!(contents.last().map(String::as_str), Some("msg 59"));
    }

    #[tokio::test]
    async fn the_history_walk_stops_when_the_caller_is_caught_up() {
        let (_tmp, _guard, owner) = init_test_db();
        let relay = MemoryRelay::new();
        let community = create_community(&relay, "Caught", vec!["wss://r".into()], None).await.unwrap();
        let general = community.channels[0].id;
        flood_general(&relay, &community, &owner, 120, 10_000).await;

        // The caller says "I hold everything" after the first page — no deeper fetch.
        let mut pages = 0usize;
        let got = fetch_channel_history(&relay, &community, &general, 50, 8, None, None, crate::community::transport::Evidence::Quorum, |_| {
            pages += 1;
            false
        })
        .await
        .unwrap();
        assert_eq!(pages, 1, "the early stop is consulted once");
        assert_eq!(got.len(), 50, "only the newest page is fetched");
        assert_eq!(got.last().map(|f| f.event.opened().rumor.content.clone()).as_deref(), Some("msg 119"));
    }

    #[tokio::test]
    async fn a_same_second_history_wall_terminates_instead_of_looping() {
        // 60 messages in ONE second with a 25-wrap page: a second-granular
        // `until` can never page past the wall — the walk must step over it
        // (bounded loss, logged) rather than spin.
        let (_tmp, _guard, owner) = init_test_db();
        let relay = MemoryRelay::new();
        let community = create_community(&relay, "Wall", vec!["wss://r".into()], None).await.unwrap();
        let general = community.channels[0].id;
        let group = channel_group_key(&community.community_root, &general, community.root_epoch);
        for i in 0..60usize {
            let rumor = chat::build_message_rumor(owner.public_key(), &general, community.root_epoch, &format!("burst {i}"), None, &[], vec![], 5_000_000 + i as u64);
            let (wrap, _) = chat::seal_chat_rumor(&rumor, &group, &owner, Timestamp::from_secs(5_000), false).unwrap();
            relay.publish(&wrap, &community.relays).await.unwrap();
        }
        let got = fetch_channel_history(&relay, &community, &general, 25, 8, None, None, crate::community::transport::Evidence::Quorum, |_| true).await.unwrap();
        assert!(got.len() >= 25, "at least the relay page is read");
        assert!(got.len() <= 60, "sane bound");
        // Termination is the assertion: reaching here means the wall didn't loop.
    }

    #[tokio::test]
    async fn a_grant_revoke_survives_a_withholding_relay() {
        // Floor persistence on the delegation plane: after the owner revokes an admin,
        // a relay serving only the OLD (still owner-signed) grant can't resurrect it.
        let (_tmp, _guard, owner) = init_test_db();
        let relay = MemoryRelay::new();
        let community = create_community(&relay, "Revoke", vec!["wss://good".into()], None).await.unwrap();
        let admin = Keys::generate();
        let rid = "d4".repeat(32);
        publish_role(&relay, &community, &owner, &admin_role(&rid, Permissions::MANAGE_METADATA), 1).await;
        publish_grant(&relay, &community, &owner, &admin.public_key(), vec![rid.clone()], 1).await;
        follow_control(&relay, &community).await.unwrap().updated; // seed floors incl. the grant at v1
        publish_grant(&relay, &community, &owner, &admin.public_key(), vec![], 2).await; // revoke → grant floor v2
        follow_control(&relay, &community).await.unwrap().updated;

        // A stale relay serves only the grant prefix (v1, the live grant).
        inject_stale_prefix(&relay, &community, 1, "wss://stale").await;
        let mut stale = community.clone();
        stale.relays = vec!["wss://stale".into()];
        let floors = load_floors(&community);
        let editions = fetch_control(&relay, &stale).await;
        let authority = fold_authority(&stale, &editions, &floors);
        assert!(
            !authority.roles.is_authorized(&admin.public_key().to_hex(), Some(&owner.public_key().to_hex()), Permissions::MANAGE_METADATA),
            "the persisted grant floor refuses the rolled-back (re-granted) view"
        );
    }

    /// Load the current-epoch floors for a community (test mirror of follow_control).
    fn load_floors(community: &CommunityV2) -> Floors {
        let cid_hex = crate::simd::hex::bytes_to_hex_32(&community.id().0);
        crate::db::community::get_all_edition_heads_full(&cid_hex)
            .unwrap_or_default()
            .into_iter()
            .filter(|(_, f)| f.0 == community.root_epoch.0)
            .map(|(e, f)| (e, (f.1, f.2, f.3)))
            .collect()
    }

    /// Fetch + open every control edition at a community's control plane (test helper).
    async fn fetch_control(relay: &MemoryRelay, community: &CommunityV2) -> Vec<ParsedEdition> {
        let group = control::ControlPlane::of(&community).write_group().unwrap();
        let q = Query { kinds: vec![stream::KIND_WRAP], authors: vec![group.pk_hex()], limit: Some(500), ..Default::default() };
        relay
            .fetch(&q, &community.relays)
            .await
            .unwrap_or_default()
            .iter()
            .filter_map(|w| control::open_control_edition(w, &group).ok().map(|(ed, _)| ed))
            .collect()
    }

    #[tokio::test]
    async fn follow_control_is_a_noop_on_a_freshly_created_community() {
        let (_tmp, _guard, _owner) = init_test_db();
        let relay = MemoryRelay::new();
        let community = create_community(&relay, "Fresh", vec!["wss://r".into()], None).await.unwrap();
        // Only the genesis editions exist; folding them reproduces the held view.
        assert!(follow_control(&relay, &community).await.unwrap().updated.is_none());
    }

    #[tokio::test]
    async fn follow_control_adds_a_new_public_channel_and_re_subscribes_it() {
        let (_tmp, _guard, owner) = init_test_db();
        let relay = MemoryRelay::new();
        let community = create_community(&relay, "Grow", vec!["wss://r".into()], None).await.unwrap();
        let new_id = ChannelId([0x5a; 32]);
        publish_channel_edition(&relay, &community, &owner, &new_id, "announcements", false, 1, false).await;

        let updated = follow_control(&relay, &community).await.unwrap().updated.expect("a new channel changed the view");
        assert_eq!(updated.channels.len(), 2);
        let added = updated.channel(&new_id).expect("the new channel folded in");
        assert_eq!(added.name, "announcements");
        assert!(!added.private);
        assert_eq!(added.key, None, "a public channel derives from the root (no stored key)");

        // The new channel is now in the realtime author-set (it would be subscribed).
        let authors = super::super::realtime::plane_authors(std::slice::from_ref(&updated));
        let addr = channel_group_key(&updated.community_root, &new_id, updated.root_epoch).pk();
        assert!(authors.contains(&addr), "the added channel joins the live subscription");

        // Persisted: a reload sees it too.
        let reloaded = crate::db::community::load_community_v2(community.id()).unwrap().unwrap();
        assert!(reloaded.channel(&new_id).is_some());
    }

    #[tokio::test]
    async fn follow_control_renames_the_community_and_an_existing_channel() {
        let (_tmp, _guard, owner) = init_test_db();
        let relay = MemoryRelay::new();
        let community = create_community(&relay, "Old Name", vec!["wss://r".into()], None).await.unwrap();
        let general = community.channels[0].id;
        // A v2 metadata edition renames the community; a v2 channel edition renames #general.
        publish_community_meta(&relay, &community, &owner, "New Name", 2).await;
        publish_channel_edition(&relay, &community, &owner, &general, "lobby", false, 2, false).await;

        let updated = follow_control(&relay, &community).await.unwrap().updated.unwrap();
        assert_eq!(updated.name, "New Name");
        assert_eq!(updated.channel(&general).unwrap().name, "lobby");
        assert_eq!(updated.channels.len(), 1, "a rename doesn't add a channel");
    }

    #[tokio::test]
    async fn follow_control_deletes_a_channel() {
        let (_tmp, _guard, owner) = init_test_db();
        let relay = MemoryRelay::new();
        let community = create_community(&relay, "Prune", vec!["wss://r".into()], None).await.unwrap();
        let extra = ChannelId([0x77; 32]);

        // The channel is first added and folded into the held view.
        publish_channel_edition(&relay, &community, &owner, &extra, "temp", false, 1, false).await;
        let with_extra = follow_control(&relay, &community).await.unwrap().updated.expect("added");
        assert!(with_extra.channel(&extra).is_some());

        // Then it's tombstoned — the delete (higher version) folds the held one back out.
        publish_channel_edition(&relay, &community, &owner, &extra, "temp", false, 2, true).await;
        let updated = follow_control(&relay, &with_extra).await.unwrap().updated.expect("removed");
        assert!(updated.channel(&extra).is_none(), "a deleted channel folds out");
        assert_eq!(updated.channels.len(), 1, "only #general remains");
    }

    /// Re-inject only the OLD prefix (every edition at/below `max_version`) of a
    /// community's control plane onto a second relay URL — the withholding-relay
    /// simulation: everything it serves is genuinely owner-signed, just stale.
    async fn inject_stale_prefix(relay: &MemoryRelay, community: &CommunityV2, max_version: u64, stale_relay: &str) {
        let group = control::ControlPlane::of(&community).write_group().unwrap();
        let query = Query { kinds: vec![stream::KIND_WRAP], authors: vec![group.pk_hex()], limit: Some(500), ..Default::default() };
        let wraps = relay.fetch(&query, &community.relays).await.unwrap();
        for w in &wraps {
            if let Ok((ed, _)) = control::open_control_edition(w, &group) {
                if ed.version <= max_version {
                    relay.inject(w, &[stale_relay.to_string()]);
                }
            }
        }
    }

    #[tokio::test]
    async fn a_withholding_relay_cannot_roll_back_a_rename() {
        // W2 persisted floor: after adopting the owner's v2 rename, a relay serving
        // only the (owner-signed) v1 genesis must not revert the held name.
        let (_tmp, _guard, owner) = init_test_db();
        let relay = MemoryRelay::new();
        let community = create_community(&relay, "Original", vec!["wss://good".into()], None).await.unwrap();
        publish_community_meta(&relay, &community, &owner, "Renamed", 2).await;

        let updated = follow_control(&relay, &community).await.unwrap().updated.expect("rename adopted");
        assert_eq!(updated.name, "Renamed");

        // The stale relay holds only the genesis prefix; point the follow at it.
        inject_stale_prefix(&relay, &community, 1, "wss://stale").await;
        let mut stale_view = updated.clone();
        stale_view.relays = vec!["wss://stale".into()];
        assert!(
            follow_control(&relay, &stale_view).await.unwrap().updated.is_none(),
            "a stale-only relay must not change the held view"
        );
        let held = crate::db::community::load_community_v2(community.id()).unwrap().unwrap();
        assert_eq!(held.name, "Renamed", "the persisted floor refuses the rollback");
    }

    #[tokio::test]
    async fn a_withholding_relay_cannot_resurrect_a_deleted_channel() {
        let (_tmp, _guard, owner) = init_test_db();
        let relay = MemoryRelay::new();
        let community = create_community(&relay, "Prune2", vec!["wss://good".into()], None).await.unwrap();
        let extra = ChannelId([0x44; 32]);

        // A same-content metadata edit: no visible change (None), but the floor must
        // still advance to v2 (so the genesis metadata can't re-present below).
        publish_community_meta(&relay, &community, &owner, "Prune2", 2).await;
        assert!(follow_control(&relay, &community).await.unwrap().updated.is_none());

        publish_channel_edition(&relay, &community, &owner, &extra, "temp", false, 1, false).await;
        let with_extra = follow_control(&relay, &community).await.unwrap().updated.expect("added");
        publish_channel_edition(&relay, &community, &owner, &extra, "temp", false, 2, true).await;
        let pruned = follow_control(&relay, &with_extra).await.unwrap().updated.expect("removed");
        assert!(pruned.channel(&extra).is_none());

        // The stale relay serves the add (v1) but withholds the delete (v2).
        inject_stale_prefix(&relay, &community, 1, "wss://stale").await;
        let mut stale_view = pruned.clone();
        stale_view.relays = vec!["wss://stale".into()];
        assert!(
            follow_control(&relay, &stale_view).await.unwrap().updated.is_none(),
            "the withheld delete must not resurrect the channel"
        );
        let held = crate::db::community::load_community_v2(community.id()).unwrap().unwrap();
        assert!(held.channel(&extra).is_none(), "the deleted channel stays deleted");
    }

    #[tokio::test]
    async fn a_new_epoch_bootstraps_past_an_old_epoch_floor() {
        // The Armada-convergence carve-out: a Refounding compacts the chain and
        // re-wraps a detached head at the NEW epoch's control plane. The old epoch's
        // floor must not block it — epoch-filtering makes the entity bootstrap.
        let (_tmp, _guard, owner) = init_test_db();
        let relay = MemoryRelay::new();
        let community = create_community(&relay, "Before", vec!["wss://good".into()], None).await.unwrap();
        publish_community_meta(&relay, &community, &owner, "Edited", 2).await;
        let updated = follow_control(&relay, &community).await.unwrap().updated.expect("edit adopted");
        assert_eq!(updated.name, "Edited");

        // Refounding lands (epoch bump saved by the rekey path); the compacted head
        // arrives DETACHED (high version, no prev) on the new epoch's plane.
        let refounded = rotate_view(&updated, updated.community_root, 1);
        crate::db::community::save_community_v2(&refounded).unwrap();
        publish_community_meta(&relay, &refounded, &owner, "Compacted", 5).await;

        let adopted = follow_control(&relay, &refounded).await.unwrap().updated.expect("compacted head adopted");
        assert_eq!(adopted.name, "Compacted", "a fresh epoch bootstraps despite the dangling prev");
        // The persisted floor is stamped with the epoch the FOLD ran under.
        let cid_hex = crate::simd::hex::bytes_to_hex_32(&community.id().0);
        let heads = crate::db::community::get_all_edition_heads_epoched(&cid_hex).unwrap();
        assert!(
            heads.get(&cid_hex).is_some_and(|(e, v, _)| *e == 1 && *v == 5),
            "the adopted head carries the fold's epoch + version"
        );
    }

    #[tokio::test]
    async fn a_same_version_owner_fork_at_the_floor_converges_to_the_deterministic_winner() {
        // Two owner-signed editions at the SAME version (publish retry / two owner
        // devices): every client must land on the lower-inner-id winner. A hash-strict
        // floor would wedge here forever while Armada converges — the floor must
        // CONVERGE instead (the v1 decide() rule).
        let (_tmp, _guard, owner) = init_test_db();
        let relay = MemoryRelay::new();
        let community = create_community(&relay, "Fork", vec!["wss://r".into()], None).await.unwrap();
        let group = control::ControlPlane::of(&community).write_group().unwrap();
        let genesis_hash = head_hash_on_relay(&relay, &community, &community.id().0).await.unwrap();

        publish_community_meta(&relay, &community, &owner, "Ours", 2).await;
        let ours = follow_control(&relay, &community).await.unwrap().updated.expect("ours adopted");
        assert_eq!(ours.name, "Ours");

        // Our committed v2 edition's tiebreak id.
        let our_inner = {
            let q = Query { kinds: vec![stream::KIND_WRAP], authors: vec![group.pk_hex()], limit: Some(500), ..Default::default() };
            let wraps = relay.fetch(&q, &community.relays).await.unwrap();
            wraps
                .iter()
                .find_map(|w| {
                    control::open_control_edition(w, &group)
                        .ok()
                        .filter(|(ed, _)| ed.version == 2 && ed.vsk == vsk::COMMUNITY_METADATA)
                        .map(|(ed, _)| ed.inner_id)
                })
                .unwrap()
        };

        // Craft the concurrent fork so it WINS the deterministic tiebreak (vary the
        // authored timestamp until its inner id is lower).
        let meta = control::CommunityMetadata { name: "Theirs".into(), ..Default::default() };
        let content = serde_json::to_string(&meta).unwrap();
        let mut ts = 2_000u64;
        let fork_wrap = loop {
            let rumor = control::build_edition_rumor(owner.public_key(), vsk::COMMUNITY_METADATA, &community.id().0, 2, Some(&genesis_hash), &content, ts, None);
            let inner = rumor.id.unwrap().to_bytes();
            if inner < our_inner {
                break control::seal_control_edition(&rumor, &group, &owner, Timestamp::from_secs(ts)).unwrap().0;
            }
            ts += 1;
        };
        relay.publish(&fork_wrap, &community.relays).await.unwrap();

        let converged = follow_control(&relay, &ours).await.unwrap().updated.expect("fork winner adopted");
        assert_eq!(converged.name, "Theirs", "the floor converges to the lower-inner-id winner");
        let cid_hex = crate::simd::hex::bytes_to_hex_32(&community.id().0);
        let held = crate::db::community::get_edition_head_inner_id(&cid_hex, &cid_hex).unwrap();
        assert!(held.is_some_and(|h| h < our_inner), "the persisted floor's tiebreak key moved to the winner");
    }

    #[tokio::test]
    async fn an_anchored_prefix_applies_while_a_gap_above_awaits_the_missing_link() {
        // v2 chains to the floor; v4 arrives but its v3 link is withheld. The
        // chain-verified prefix (v2) applies NOW — refuse-downgrade holds for it —
        // while the detached v4 waits. When v3 lands, the chain heals to v4.
        let (_tmp, _guard, owner) = init_test_db();
        let relay = MemoryRelay::new();
        let community = create_community(&relay, "Prefix", vec!["wss://r".into()], None).await.unwrap();
        let group = control::ControlPlane::of(&community).write_group().unwrap();

        publish_community_meta(&relay, &community, &owner, "Two", 2).await;
        let v2_hash = head_hash_on_relay(&relay, &community, &community.id().0).await.unwrap();

        // Craft v3 (held back) and v4 (published, chained to the withheld v3).
        let c3 = serde_json::to_string(&control::CommunityMetadata { name: "Three".into(), ..Default::default() }).unwrap();
        let r3 = control::build_edition_rumor(owner.public_key(), vsk::COMMUNITY_METADATA, &community.id().0, 3, Some(&v2_hash), &c3, 3_000, None);
        let (w3, _) = control::seal_control_edition(&r3, &group, &owner, Timestamp::from_secs(3_000)).unwrap();
        let (ed3, _) = control::open_control_edition(&w3, &group).unwrap();
        let c4 = serde_json::to_string(&control::CommunityMetadata { name: "Four".into(), ..Default::default() }).unwrap();
        let r4 = control::build_edition_rumor(owner.public_key(), vsk::COMMUNITY_METADATA, &community.id().0, 4, Some(&ed3.self_hash), &c4, 4_000, None);
        let (w4, _) = control::seal_control_edition(&r4, &group, &owner, Timestamp::from_secs(4_000)).unwrap();
        relay.publish(&w4, &community.relays).await.unwrap();

        let updated = follow_control(&relay, &community).await.unwrap().updated.expect("the verified prefix applies");
        assert_eq!(updated.name, "Two", "the anchored prefix lands; the detached v4 does not");

        relay.publish(&w3, &community.relays).await.unwrap();
        let healed = follow_control(&relay, &updated).await.unwrap().updated.expect("the chain heals");
        assert_eq!(healed.name, "Four", "once the link arrives, the head advances past the prefix");
    }

    #[tokio::test]
    async fn paging_rescues_a_floor_link_evicted_from_the_newest_window() {
        // The held floor is v2; the owner publishes v3, then a flood of foreign junk
        // wraps fills the newest window, then v4. Page 1 sees only v4 (detached →
        // gapped); paging older must recover v3 (and the floor link) and heal to v4.
        let (_tmp, _guard, owner) = init_test_db();
        let relay = MemoryRelay::new();
        let community = create_community(&relay, "Paged", vec!["wss://r".into()], None).await.unwrap();
        let group = control::ControlPlane::of(&community).write_group().unwrap();

        publish_community_meta(&relay, &community, &owner, "Two", 2).await;
        let base = follow_control(&relay, &community).await.unwrap().updated.expect("floor at v2");
        publish_community_meta(&relay, &base, &owner, "Three", 3).await; // ts 1_000 (old)
        let v3_hash = head_hash_on_relay(&relay, &community, &community.id().0).await.unwrap();

        // Rogue flood occupying the newest window (sealed to the control plane, but
        // non-owner — the authority gate drops them; they only crowd the page).
        let rogue = Keys::generate();
        for i in 0..(FOLLOW_PAGE as u64 - 1) {
            let rumor = control::build_edition_rumor(rogue.public_key(), vsk::CHANNEL_METADATA, &[0xCC; 32], 1, None, "{\"name\":\"junk\",\"private\":false}", 4_000 + i, None);
            let (w, _) = control::seal_control_edition(&rumor, &group, &rogue, Timestamp::from_secs(4_000 + i)).unwrap();
            relay.publish(&w, &community.relays).await.unwrap();
        }
        // v4 chained to the real v3 (crafted directly: the flood also blinds the
        // helper's own newest-window head lookup), timestamped newest of all.
        let c4 = serde_json::to_string(&control::CommunityMetadata { name: "Four".into(), ..Default::default() }).unwrap();
        let r4 = control::build_edition_rumor(owner.public_key(), vsk::COMMUNITY_METADATA, &community.id().0, 4, Some(&v3_hash), &c4, 10_000, None);
        let (w4, _) = control::seal_control_edition(&r4, &group, &owner, Timestamp::from_secs(10_000)).unwrap();
        relay.publish(&w4, &community.relays).await.unwrap();

        let healed = follow_control(&relay, &base).await.unwrap().updated.expect("paging recovered the chain");
        assert_eq!(healed.name, "Four", "the gap paged past the flood to the floor link");
    }

